def ackermann(m, n):
    if m == 0:
        return n + 1
    if n == 0:
        return ackermann(m - 1, 1)
    return ackermann(m - 1, ackermann(m, n - 1))

def ackermann(m, n):
    if m == 0:
        return n + 1
    if m == 1:
        return n + 2
    if m == 2:
        return 2 * n + 3
    return 2 ** (n + 3) - 3

function ackermann(m, n) {
  if (m === 0) return n + 1;
  if (m === 1) return n + 2;
  if (m === 2) return 2 * n + 3;
  return Math.pow(2, n + 3) - 3;
}

class Solution {
    public int ackermann(int m, int n) {
        if (m == 0) return n + 1;
        if (m == 1) return n + 2;
        if (m == 2) return 2 * n + 3;
        return (1 << (n + 3)) - 3;
    }
}

