function addBinary(a, b) {
  let i = a.length - 1, j = b.length - 1, carry = 0;
  const digits = [];
  while (i >= 0 || j >= 0 || carry > 0) {
    let total = carry;
    if (i >= 0) total += a.charCodeAt(i--) - 48;
    if (j >= 0) total += b.charCodeAt(j--) - 48;
    digits.push(total % 2);
    carry = Math.floor(total / 2);
  }
  let result = digits.reverse().join("").replace(/^0+/, "");
  return result === "" ? "0" : result;
}

class Solution {
    public String addBinary(String a, String b) {
        int i = a.length() - 1, j = b.length() - 1, carry = 0;
        StringBuilder digits = new StringBuilder();
        while (i >= 0 || j >= 0 || carry > 0) {
            int total = carry;
            if (i >= 0) total += a.charAt(i--) - '0';
            if (j >= 0) total += b.charAt(j--) - '0';
            digits.append(total % 2);
            carry = total / 2;
        }
        digits.reverse();
        int start = 0;
        while (start < digits.length() - 1 && digits.charAt(start) == '0') start++;
        return digits.substring(start);
    }
}

string add_binary(string a, string b) {
    int i = (int) a.size() - 1, j = (int) b.size() - 1, carry = 0;
    string digits;
    while (i >= 0 || j >= 0 || carry > 0) {
        int total = carry;
        if (i >= 0) total += a[i--] - '0';
        if (j >= 0) total += b[j--] - '0';
        digits += (char) ('0' + total % 2);
        carry = total / 2;
    }
    reverse(digits.begin(), digits.end());
    size_t start = 0;
    while (start + 1 < digits.size() && digits[start] == '0') start++;
    return digits.substr(start);
}

