def count_dag_paths(n, edges):
    adjacent = [[] for _ in range(n)]
    for a, b in edges:
        adjacent[a].append(b)

    def walk(u):
        if u == n - 1:
            return 1
        return sum(walk(v) for v in adjacent[u])

    return walk(0)

def count_dag_paths(n, edges):
    adjacent = [[] for _ in range(n)]
    for a, b in edges:
        adjacent[a].append(b)
    memo = {}

    def ways(u):
        if u == n - 1:
            return 1
        if u not in memo:
            memo[u] = sum(ways(v) for v in adjacent[u])
        return memo[u]

    return ways(0)

function countDagPaths(n, edges) {
  const adjacent = [];
  for (let i = 0; i < n; i++) adjacent.push([]);
  for (const [a, b] of edges) adjacent[a].push(b);
  const memo = new Array(n).fill(-1);
  function ways(u) {
    if (u === n - 1) return 1;
    if (memo[u] >= 0) return memo[u];
    let total = 0;
    for (const v of adjacent[u]) total += ways(v);
    memo[u] = total;
    return total;
  }
  return ways(0);
}

class Solution {
