    private int n;

    private long ways(int u) {
        if (u == n - 1) return 1;
        if (memo[u] >= 0) return memo[u];
        long total = 0;
        for (int v : adjacent.get(u)) total += ways(v);
        memo[u] = total;
        return total;
    }

    public int countDagPaths(int n, int[][] edges) {
        this.n = n;
        adjacent = new ArrayList<>();
        for (int i = 0; i < n; i++) adjacent.add(new ArrayList<>());
        for (int[] e : edges) adjacent.get(e[0]).add(e[1]);
        memo = new long[n];
        Arrays.fill(memo, -1);
        return (int) ways(0);
    }
}

long long dag_ways(int u, int n, vector<vector<int>>& adjacent, vector<long long>& memo) {
    if (u == n - 1) return 1;
    if (memo[u] >= 0) return memo[u];
    long long total = 0;
    for (int v : adjacent[u]) total += dag_ways(v, n, adjacent, memo);
    memo[u] = total;
    return total;
}

