def count_anagram_windows(text, pattern):
    m = len(pattern)
    target = sorted(pattern)
    return sum(1 for i in range(len(text) - m + 1) if sorted(text[i:i + m]) == target)

def count_anagram_windows(text, pattern):
    m = len(pattern)
    if len(text) < m:
        return 0
    need = [0] * 26
    have = [0] * 26
    for ch in pattern:
        need[ord(ch) - 97] += 1
    for ch in text[:m]:
        have[ord(ch) - 97] += 1
    result = 1 if have == need else 0
    for i in range(m, len(text)):
        have[ord(text[i]) - 97] += 1
        have[ord(text[i - m]) - 97] -= 1
        if have == need:
            result += 1
    return result

function countAnagramWindows(text, pattern) {
  const m = pattern.length;
  if (text.length < m) return 0;
  const need = new Array(26).fill(0), have = new Array(26).fill(0);
  for (const ch of pattern) need[ch.charCodeAt(0) - 97]++;
  for (let i = 0; i < m; i++) have[text.charCodeAt(i) - 97]++;
  const same = () => { for (let c = 0; c < 26; c++) if (need[c] !== have[c]) return false; return true; };
  let result = same() ? 1 : 0;
  for (let i = m; i < text.length; i++) {
    have[text.charCodeAt(i) - 97]++;
    have[text.charCodeAt(i - m) - 97]--;
    if (same()) result++;
  }
  return result;
}

class Solution {
    public int countAnagramWindows(String text, String pattern) {
        int m = pattern.length();
        if (text.length() < m) return 0;
        int[] need = new int[26], have = new int[26];
        for (int i = 0; i < m; i++) { need[pattern.charAt(i) - 'a']++; have[text.charAt(i) - 'a']++; }
        int result = Arrays.equals(need, have) ? 1 : 0;
        for (int i = m; i < text.length(); i++) {
            have[text.charAt(i) - 'a']++;
            have[text.charAt(i - m) - 'a']--;
            if (Arrays.equals(need, have)) result++;
        }
        return result;
    }
}

