def bag_of_tokens_score(tokens, power):
    n = len(tokens)

    def go(mask, power, score):
        best = score
        for i in range(n):
            if mask >> i & 1:
                continue
            if power >= tokens[i]:
                best = max(best, go(mask | 1 << i, power - tokens[i], score + 1))
            if score >= 1:
                best = max(best, go(mask | 1 << i, power + tokens[i], score - 1))
        return best

    return go(0, power, 0)

function bagOfTokensScore(tokens, power) {
  const a = tokens.slice().sort((p, q) => p - q);
  let lo = 0, hi = a.length - 1, score = 0, best = 0;
  while (lo <= hi) {
    if (power >= a[lo]) { power -= a[lo]; lo++; score++; best = Math.max(best, score); }
    else if (score > 0) { power += a[hi]; hi--; score--; }
    else break;
  }
  return best;
}

