def is_balanced(text):
    previous = None
    while previous != text:
        previous = text
        text = text.replace("()", "").replace("[]", "").replace("{}", "")
    return text == ""

def is_balanced(text):
    match = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif not stack or stack.pop() != match[ch]:
            return False
    return not stack

function isBalanced(text) {
  const match = { ")": "(", "]": "[", "}": "{" };
  const stack = [];
  for (const ch of text) {
    if (ch === "(" || ch === "[" || ch === "{") stack.push(ch);
    else if (stack.length === 0 || stack.pop() !== match[ch]) return false;
  }
  return stack.length === 0;
}

class Solution {
    public boolean isBalanced(String text) {
        char[] stack = new char[text.length()];
        int top = 0;
        for (char ch : text.toCharArray()) {
            if (ch == '(' || ch == '[' || ch == '{') {
                stack[top++] = ch;
            } else {
                if (top == 0) return false;
                char open = stack[--top];
                if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) return false;
            }
        }
        return top == 0;
    }
}

bool is_balanced(string text) {
