    for (char ch : text) {
        if (ch == '(' || ch == '[' || ch == '{') {
            stack.push_back(ch);
        } else {
            if (stack.empty()) return false;
            char open = stack.back();
            stack.pop_back();
            if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) return false;
        }
    }
    return stack.empty();
}

def balloon_burst_max(balloons):
    def best(arr):
        if not arr:
            return 0
        top = 0
        for i in range(len(arr)):
            left = arr[i - 1] if i > 0 else 1
            right = arr[i + 1] if i + 1 < len(arr) else 1
            gain = left * arr[i] * right + best(arr[:i] + arr[i + 1:])
            if gain > top:
                top = gain
        return top

    return best(balloons)

