def total_score(ops):
    record = []
    for op in ops.split(" "):
        if op == "+":
            record.append(sum(record[-2:]))
        elif op == "D":
            record.append(2 * record[-1])
        elif op == "C":
            record = record[:-1]
        else:
            record = record + [int(op)]
    return sum(record)

def total_score(ops):
    stack = []
    total = 0
    for op in ops.split(" "):
        if op == "C":
            total -= stack.pop()
            continue
        if op == "+":
            value = stack[-1] + stack[-2]
        elif op == "D":
            value = 2 * stack[-1]
        else:
            value = int(op)
        stack.append(value)
