def cable_moves_needed(n, cables):
    if len(cables) < n - 1:
        return -1
    neighbours = [[] for _ in range(n)]
    for a, b in cables:
        neighbours[a].append(b)
        neighbours[b].append(a)
    seen = [False] * n
    groups = 0
    for start in range(n):
        if seen[start]:
            continue
        groups += 1
        stack = [start]
        seen[start] = True
        while stack:
            u = stack.pop()
            for v in neighbours[u]:
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
    return groups - 1

