}

int cable_moves_needed(int n, vector<vector<int>>& cables) {
    if ((int) cables.size() < n - 1) return -1;
    vector<int> parent(n);
    for (int i = 0; i < n; i++) parent[i] = i;
    int groups = n;
    for (auto& cable : cables) {
        int ra = dsu_find(parent, cable[0]), rb = dsu_find(parent, cable[1]);
        if (ra != rb) { parent[ra] = rb; groups--; }
    }
    return groups - 1;
}

def calculate_expression(expression):
    s = expression.replace(" ", "")
    pos = [0]

    def number():
        start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        return int(s[start:pos[0]])

    def term():
        if s[pos[0]] == "(":
            pos[0] += 1
            value = expr()
            pos[0] += 1
            return value
        return number()

    def expr():
        value = term()
        while pos[0] < len(s) and s[pos[0]] in "+-":
            op = s[pos[0]]
            pos[0] += 1
            rhs = term()
            value = value + rhs if op == "+" else value - rhs
        return value

    return expr()

def calculate_expression(expression):
    result, number, sign = 0, 0, 1
    stack = []
    for ch in expression:
        if ch.isdigit():
            number = number * 10 + int(ch)
        elif ch == "+" or ch == "-":
            result += sign * number
            number = 0
            sign = 1 if ch == "+" else -1
        elif ch == "(":
            stack.append(result)
            stack.append(sign)
            result, sign = 0, 1
        elif ch == ")":
            result += sign * number
            number = 0
            result *= stack.pop()
            result += stack.pop()
    return result + sign * number

function calculateExpression(expression) {
  let result = 0, number = 0, sign = 1;
  const stack = [];
  for (const ch of expression) {
    if (ch >= "0" && ch <= "9") number = number * 10 + (ch.charCodeAt(0) - 48);
    else if (ch === "+" || ch === "-") { result += sign * number; number = 0; sign = ch === "+" ? 1 : -1; }
    else if (ch === "(") { stack.push(result); stack.push(sign); result = 0; sign = 1; }
    else if (ch === ")") {
      result += sign * number;
      number = 0;
      result *= stack.pop();
      result += stack.pop();
    }
  }
  return result + sign * number;
}

class Solution {
    public int calculateExpression(String expression) {
        long result = 0, number = 0;
        int sign = 1;
        Deque<Long> stack = new ArrayDeque<>();
        for (char ch : expression.toCharArray()) {
            if (ch >= '0' && ch <= '9') number = number * 10 + (ch - '0');
            else if (ch == '+' || ch == '-') { result += sign * number; number = 0; sign = ch == '+' ? 1 : -1; }
            else if (ch == '(') { stack.push(result); stack.push((long) sign); result = 0; sign = 1; }
            else if (ch == ')') {
                result += sign * number;
                number = 0;
                result *= stack.pop();
                result += stack.pop();
            }
        }
        return (int) (result + sign * number);
    }
}

int calculate_expression(string expression) {
    long long result = 0, number = 0;
    int sign = 1;
    vector<long long> stack;
    for (char ch : expression) {
        if (ch >= '0' && ch <= '9') number = number * 10 + (ch - '0');
        else if (ch == '+' || ch == '-') { result += sign * number; number = 0; sign = ch == '+' ? 1 : -1; }
        else if (ch == '(') { stack.push_back(result); stack.push_back(sign); result = 0; sign = 1; }
        else if (ch == ')') {
            result += sign * number;
            number = 0;
            long long outer_sign = stack.back(); stack.pop_back();
            long long outer_result = stack.back(); stack.pop_back();
            result = outer_result + outer_sign * result;
        }
    }
    return (int) (result + sign * number);
}

