def count_car_fleets(target, position, speed):
    from fractions import Fraction

    n = len(position)
    times = [Fraction(target - position[i], speed[i]) for i in range(n)]
    fleets = 0
    for i in range(n):
        ahead = [times[j] for j in range(n) if position[j] > position[i]]
        if not ahead or times[i] > max(ahead):
            fleets += 1
    return fleets

def count_car_fleets(target, position, speed):
    cars = sorted(zip(position, speed), reverse=True)
    fleets = 0
    lead_distance, lead_speed = 0, 1
    for pos, sp in cars:
        distance = target - pos
        if fleets == 0 or distance * lead_speed > lead_distance * sp:
            fleets += 1
            lead_distance, lead_speed = distance, sp
    return fleets

function countCarFleets(target, position, speed) {
  const order = position.map((p, i) => i).sort((a, b) => position[b] - position[a]);
  let fleets = 0, leadDistance = 0, leadSpeed = 1;
  for (const i of order) {
    const distance = target - position[i];
    if (fleets === 0 || distance * leadSpeed > leadDistance * speed[i]) {
      fleets++;
      leadDistance = distance;
      leadSpeed = speed[i];
    }
  }
  return fleets;
}

