def circular_street_robbery(loot):
    n = len(loot)
    best = 0
    for mask in range(1 << n):
        ok = True
        total = 0
        for i in range(n):
            if mask >> i & 1:
                if n > 1 and mask >> ((i + 1) % n) & 1:
                    ok = False
                    break
                total += loot[i]
        if ok and total > best:
            best = total
    return best

def circular_street_robbery(loot):
    def line(a):
        take, skip = 0, 0
        for x in a:
            take, skip = skip + x, max(take, skip)
        return max(take, skip)

    if len(loot) == 1:
        return loot[0]
    return max(line(loot[1:]), line(loot[:-1]))

function circularStreetRobbery(loot) {
  function line(from, to) {
    let take = 0, skip = 0;
    for (let i = from; i < to; i++) {
      const nextTake = skip + loot[i];
      skip = Math.max(take, skip);
      take = nextTake;
    }
    return Math.max(take, skip);
  }
  if (loot.length === 1) return loot[0];
  return Math.max(line(1, loot.length), line(0, loot.length - 1));
}

class Solution {
    private int line(int[] loot, int from, int to) {
        int take = 0, skip = 0;
        for (int i = from; i < to; i++) {
            int nextTake = skip + loot[i];
            skip = Math.max(take, skip);
            take = nextTake;
        }
        return Math.max(take, skip);
    }

    public int circularStreetRobbery(int[] loot) {
