def is_clean_palindrome(text):
    cleaned = [c.lower() for c in text if c.isalnum()]
    return cleaned == cleaned[::-1]

def is_clean_palindrome(text):
    i, j = 0, len(text) - 1
    while i < j:
        if not text[i].isalnum():
            i += 1
        elif not text[j].isalnum():
            j -= 1
        elif text[i].lower() != text[j].lower():
            return False
        else:
            i += 1
            j -= 1
    return True

function isCleanPalindrome(text) {
  const ok = (ch) => /[a-z0-9]/i.test(ch);
  let i = 0, j = text.length - 1;
  while (i < j) {
    if (!ok(text[i])) i++;
    else if (!ok(text[j])) j--;
    else if (text[i].toLowerCase() !== text[j].toLowerCase()) return false;
    else { i++; j--; }
  }
  return true;
}

class Solution {
    public boolean isCleanPalindrome(String text) {
        int i = 0, j = text.length() - 1;
        while (i < j) {
            char a = text.charAt(i), b = text.charAt(j);
            if (!Character.isLetterOrDigit(a)) i++;
            else if (!Character.isLetterOrDigit(b)) j--;
            else if (Character.toLowerCase(a) != Character.toLowerCase(b)) return false;
            else { i++; j--; }
        }
        return true;
    }
}

