        else if (!isalnum((unsigned char) text[j])) j--;
        else if (tolower((unsigned char) text[i]) != tolower((unsigned char) text[j])) return false;
        else { i++; j--; }
    }
    return true;
}

def furthest_building(heights, bricks, ladders):
    best = 0
    climbs = []
    for i in range(len(heights) - 1):
        if heights[i + 1] > heights[i]:
            climbs.append(heights[i + 1] - heights[i])
        need = sorted(climbs, reverse=True)[ladders:]
        if sum(need) <= bricks:
            best = i + 1
        else:
            break
    return best

def furthest_building(heights, bricks, ladders):
    import heapq

    used = []
    for i in range(len(heights) - 1):
        climb = heights[i + 1] - heights[i]
        if climb <= 0:
            continue
        heapq.heappush(used, climb)
        if len(used) > ladders:
            bricks -= heapq.heappop(used)
            if bricks < 0:
                return i
    return len(heights) - 1

function furthestBuilding(heights, bricks, ladders) {
  const used = []; // climbs covered by ladders, kept as a min-heap
  function push(x) {
    used.push(x);
    let i = used.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (used[p] <= used[i]) break;
      [used[p], used[i]] = [used[i], used[p]];
      i = p;
    }
  }
  function pop() {
    const top = used[0], last = used.pop();
    if (used.length > 0) {
      used[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < used.length && used[l] < used[m]) m = l;
        if (r < used.length && used[r] < used[m]) m = r;
        if (m === i) break;
        [used[i], used[m]] = [used[m], used[i]];
        i = m;
      }
    }
    return top;
  }
  for (let i = 0; i + 1 < heights.length; i++) {
    const climb = heights[i + 1] - heights[i];
    if (climb <= 0) continue;
    push(climb);
    if (used.length > ladders) {
      bricks -= pop();
      if (bricks < 0) return i;
    }
  }
  return heights.length - 1;
}

class Solution {
    public int furthestBuilding(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> used = new PriorityQueue<>();
        long left = bricks;
        for (int i = 0; i + 1 < heights.length; i++) {
            int climb = heights[i + 1] - heights[i];
            if (climb <= 0) continue;
            used.add(climb);
            if (used.size() > ladders) {
                left -= used.poll();
                if (left < 0) return i;
            }
        }
        return heights.length - 1;
    }
}

int furthest_building(vector<int>& heights, int bricks, int ladders) {
    priority_queue<int, vector<int>, greater<int>> used;
    long long left = bricks;
    for (int i = 0; i + 1 < (int) heights.size(); i++) {
        int climb = heights[i + 1] - heights[i];
        if (climb <= 0) continue;
        used.push(climb);
        if ((int) used.size() > ladders) {
            left -= used.top();
            used.pop();
            if (left < 0) return i;
        }
    }
    return (int) heights.size() - 1;
}

def count_smooth_orders(numbers, gap):
    from itertools import permutations

    return sum(1 for p in permutations(numbers) if all(abs(p[i] - p[i + 1]) <= gap for i in range(len(p) - 1)))

def count_smooth_orders(numbers, gap):
    n = len(numbers)
    used = [False] * n

    def go(placed, last):
        if placed == n:
            return 1
        total = 0
        for i in range(n):
            if not used[i] and (placed == 0 or abs(numbers[i] - last) <= gap):
                used[i] = True
                total += go(placed + 1, numbers[i])
                used[i] = False
        return total

    return go(0, 0)

function countSmoothOrders(numbers, gap) {
  const n = numbers.length;
  const used = new Array(n).fill(false);
  function go(placed, last) {
    if (placed === n) return 1;
    let total = 0;
    for (let i = 0; i < n; i++) {
      if (!used[i] && (placed === 0 || Math.abs(numbers[i] - last) <= gap)) {
        used[i] = true;
        total += go(placed + 1, numbers[i]);
        used[i] = false;
      }
    }
    return total;
  }
  return go(0, 0);
}

