    need = {}
    for x in numbers:
        if count[x] == 0:
            continue
        count[x] -= 1
        if need.get(x, 0) > 0:
            need[x] -= 1
            need[x + 1] = need.get(x + 1, 0) + 1
        elif count.get(x + 1, 0) > 0 and count.get(x + 2, 0) > 0:
            count[x + 1] -= 1
            count[x + 2] -= 1
            need[x + 3] = need.get(x + 3, 0) + 1
