        for (int[] e : adj.get(u)) {
            int v = e[0], id = e[1];
            if (id == via) continue;
            if (order[v] == -1) {
                visit(v, id);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > order[u]) found++;
            } else {
                low[u] = Math.min(low[u], order[v]);
            }
        }
    }

