function doubleDigitList(head) {
  const digits = [];
  for (let node = head; node !== null; node = node.next) digits.push(node.val);
  let carry = 0;
  for (let i = digits.length - 1; i >= 0; i--) {
    const v = digits[i] * 2 + carry;
    digits[i] = v % 10;
    carry = Math.floor(v / 10);
  }
  if (carry > 0) digits.unshift(carry);
  const dummy = new ListNode(0, null);
  let tail = dummy;
  for (const d of digits) { tail.next = new ListNode(d, null); tail = tail.next; }
  return dummy.next;
}

class Solution {
    public ListNode doubleDigitList(ListNode head) {
        List<Integer> digits = new ArrayList<>();
        for (ListNode node = head; node != null; node = node.next) digits.add(node.val);
        int carry = 0;
        for (int i = digits.size() - 1; i >= 0; i--) {
            int v = digits.get(i) * 2 + carry;
            digits.set(i, v % 10);
            carry = v / 10;
        }
        if (carry > 0) digits.add(0, carry);
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int d : digits) { tail.next = new ListNode(d); tail = tail.next; }
        return dummy.next;
    }
}

