        if node is None:
            return 0
        acc += node.val
        return (1 if acc == target else 0) + from_node(node.left, acc) + from_node(node.right, acc)

    def everywhere(node):
        if node is None:
            return 0
        return from_node(node, 0) + everywhere(node.left) + everywhere(node.right)

    return everywhere(root)

