        if (i, j) not in memo:
            if source[i] == target[j]:
                memo[(i, j)] = go(i + 1, j + 1)
            else:
                memo[(i, j)] = 1 + min(go(i + 1, j), go(i, j + 1), go(i + 1, j + 1))
        return memo[(i, j)]

    import sys

