                continue
            seen = {(r, c)}
            stack = [(r, c)]
            escapes = False
            while stack and not escapes:
                x, y = stack.pop()
                if x == 0 or y == 0 or x == rows - 1 or y == cols - 1:
                    escapes = True
                    break
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
