  function go(i) {
    if (i === items.length) { best = Math.min(best, Math.max(...totals)); return; }
    const seen = new Set();
    for (let c = 0; c < children; c++) {
      if (seen.has(totals[c])) continue;
      seen.add(totals[c]);
      if (totals[c] + items[i] >= best) continue;
      totals[c] += items[i];
      go(i + 1);
      totals[c] -= items[i];
    }
  }
  go(0);
  return best;
}

class Solution {
    private int[] items;
    private int[] totals;
    private int best;

    private void go(int i) {
        if (i == items.length) {
            int worst = 0;
            for (int t : totals) worst = Math.max(worst, t);
            best = Math.min(best, worst);
            return;
        }
        Set<Integer> seen = new HashSet<>();
        for (int c = 0; c < totals.length; c++) {
            if (!seen.add(totals[c])) continue;
            if (totals[c] + items[i] >= best) continue;
            totals[c] += items[i];
            go(i + 1);
            totals[c] -= items[i];
        }
    }

    public int fairCookieSplit(int[] bags, int children) {
        items = bags.clone();
        Arrays.sort(items);
        for (int a = 0, b = items.length - 1; a < b; a++, b--) { int t = items[a]; items[a] = items[b]; items[b] = t; }
        totals = new int[children];
        best = 1;
        for (int x : items) best += x;
        go(0);
        return best;
    }
}

void cookie_go(const vector<int>& items, vector<int>& totals, int& best, int i) {
    if (i == (int) items.size()) {
