def grid_has_path(grid, word):
    rows, cols = len(grid), len(grid[0])
    m = len(word)
    if m == 0:
        return True

    def extend(path):
        if len(path) == m:
            return [grid[r][c] for r, c in path] == list(word)
        r, c = path[-1]
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in path:
                if extend(path + [(nr, nc)]):
                    return True
        return False

    return any(extend([(r, c)]) for r in range(rows) for c in range(cols))

def grid_has_path(grid, word):
    rows, cols = len(grid), len(grid[0])
    m = len(word)
    if m == 0:
        return True
    used = [[False] * cols for _ in range(rows)]

    def go(r, c, i):
        if i == m - 1:
            return True
        used[r][c] = True
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and not used[nr][nc] and grid[nr][nc] == word[i + 1]:
                if go(nr, nc, i + 1):
                    used[r][c] = False
                    return True
        used[r][c] = False
        return False

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == word[0] and go(r, c, 0):
                return True
    return False

function gridHasPath(grid, word) {
  const rows = grid.length, cols = grid[0].length, m = word.length;
  if (m === 0) return true;
  const used = [];
  for (let r = 0; r < rows; r++) used.push(new Array(cols).fill(false));
  const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
  function go(r, c, i) {
    if (i === m - 1) return true;
    used[r][c] = true;
    for (let d = 0; d < 4; d++) {
      const nr = r + dr[d], nc = c + dc[d];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !used[nr][nc] && grid[nr][nc] === word[i + 1]) {
        if (go(nr, nc, i + 1)) { used[r][c] = false; return true; }
      }
    }
    used[r][c] = false;
    return false;
  }
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (grid[r][c] === word[0] && go(r, c, 0)) return true;
  return false;
}

