def is_interleaving(a, b, c):
    if len(a) + len(b) != len(c):
        return False

    def go(i, j):
        if i == len(a) and j == len(b):
            return True
        k = i + j
        if i < len(a) and a[i] == c[k] and go(i + 1, j):
            return True
        if j < len(b) and b[j] == c[k] and go(i, j + 1):
            return True
        return False

    return go(0, 0)

