    row[0] = True
    for j in range(1, n + 1):
        row[j] = row[j - 1] and b[j - 1] == c[j - 1]
    for i in range(1, m + 1):
        row[0] = row[0] and a[i - 1] == c[i - 1]
        for j in range(1, n + 1):
            row[j] = (row[j] and a[i - 1] == c[i + j - 1]) or (row[j - 1] and b[j - 1] == c[i + j - 1])
    return row[n]

