def max_value(weights, values, capacity):
    n = len(weights)
    best = 0
    for mask in range(1 << n):
        weight = value = 0
        for i in range(n):
            if mask >> i & 1:
                weight += weights[i]
                value += values[i]
        if weight <= capacity:
            best = max(best, value)
    return best

