    memo = {}

    def go(i, remaining):
        if i == len(weights):
            return 0
        if (i, remaining) not in memo:
            result = go(i + 1, remaining)
            if weights[i] <= remaining:
                result = max(result, values[i] + go(i + 1, remaining - weights[i]))
            memo[(i, remaining)] = result
        return memo[(i, remaining)]

    return go(0, capacity)

