def lamps_needed(root):
    from itertools import combinations

    if root is None:
        return 0
    ids = {}
    queue = [root]
    for node in queue:
        ids[id(node)] = len(ids)
        for child in (node.left, node.right):
            if child is not None:
                queue.append(child)
    n = len(ids)
    close = [{i} for i in range(n)]
    for node in queue:
        for child in (node.left, node.right):
            if child is not None:
                a, b = ids[id(node)], ids[id(child)]
                close[a].add(b)
                close[b].add(a)
    for size in range(1, n + 1):
        for chosen in combinations(range(n), size):
            lit = set()
            for c in chosen:
                lit |= close[c]
            if len(lit) == n:
                return size
    return n

