def last_stone(stones):
    stones = sorted(stones)
    while len(stones) > 1:
        a = stones.pop()
        b = stones.pop()
        if a != b:
            stones.append(a - b)
            stones.sort()
    return stones[0] if stones else 0

def last_stone(stones):
    import heapq

    heap = [-s for s in stones]
    heapq.heapify(heap)
    while len(heap) > 1:
        a = -heapq.heappop(heap)
        b = -heapq.heappop(heap)
        if a != b:
            heapq.heappush(heap, -(a - b))
    return -heap[0] if heap else 0

function lastStone(stones) {
  const pile = [...stones].sort((a, b) => a - b);
  while (pile.length > 1) {
    const a = pile.pop(), b = pile.pop();
    if (a !== b) { pile.push(a - b); pile.sort((x, y) => x - y); }
  }
  return pile.length ? pile[0] : 0;
}

class Solution {
    public int lastStone(int[] stones) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int s : stones) heap.add(s);
        while (heap.size() > 1) {
            int a = heap.poll(), b = heap.poll();
            if (a != b) heap.add(a - b);
        }
        return heap.isEmpty() ? 0 : heap.peek();
    }
}

