def level_sums(root):
    # depth-first: add every value into the total of its depth
    sums = {}

    def visit(node, depth):
        if node is None:
            return
        sums[depth] = sums.get(depth, 0) + node.val
        visit(node.left, depth + 1)
        visit(node.right, depth + 1)

    visit(root, 0)
    return [sums[d] for d in range(len(sums))]

def level_sums(root):
    if root is None:
        return []
    result = []
    level = [root]
    while level:
        result.append(sum(node.val for node in level))
        level = [child for node in level for child in (node.left, node.right) if child]
    return result

function levelSums(root) {
  if (root === null) return [];
  const result = [];
  let level = [root];
  while (level.length > 0) {
    let total = 0;
    const next = [];
    for (const node of level) {
      total += node.val;
      if (node.left !== null) next.push(node.left);
      if (node.right !== null) next.push(node.right);
    }
    result.push(total);
    level = next;
  }
  return result;
}

class Solution {
    public int[] levelSums(TreeNode root) {
        List<Integer> sums = new ArrayList<>();
        if (root != null) {
            Deque<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            while (!queue.isEmpty()) {
                int size = queue.size();
                int total = 0;
                for (int i = 0; i < size; i++) {
                    TreeNode node = queue.poll();
                    total += node.val;
                    if (node.left != null) queue.add(node.left);
                    if (node.right != null) queue.add(node.right);
                }
                sums.add(total);
            }
        }
        int[] result = new int[sums.size()];
        for (int i = 0; i < result.length; i++) result[i] = sums.get(i);
        return result;
    }
}

vector<int> level_sums(TreeNode* root) {
    vector<int> result;
    if (root == nullptr) return result;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int size = (int) q.size();
        int total = 0;
        for (int i = 0; i < size; i++) {
            TreeNode* node = q.front();
            q.pop();
            total += node->val;
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        result.push_back(total);
    }
    return result;
}

