def longest_arithmetic_run(numbers):
    n = len(numbers)
    best = min(n, 2)
    for i in range(n):
        for j in range(i + 1, n):
            d = numbers[j] - numbers[i]
            length = 2
            last = numbers[j]
            for k in range(j + 1, n):
                if numbers[k] == last + d:
                    length += 1
                    last = numbers[k]
            best = max(best, length)
    return best

def longest_arithmetic_run(numbers):
    n = len(numbers)
    best = min(n, 2)
    table = [dict() for _ in range(n)]
    for j in range(n):
        for i in range(j):
            d = numbers[j] - numbers[i]
            table[j][d] = table[i].get(d, 1) + 1
            best = max(best, table[j][d])
    return best

function longestArithmeticRun(numbers) {
  const n = numbers.length;
  let best = Math.min(n, 2);
  const table = [];
  for (let j = 0; j < n; j++) {
    table.push(new Map());
    for (let i = 0; i < j; i++) {
      const d = numbers[j] - numbers[i];
      const length = (table[i].get(d) || 1) + 1;
      table[j].set(d, length);
      if (length > best) best = length;
    }
  }
  return best;
}

class Solution {
    public int longestArithmeticRun(int[] numbers) {
        int n = numbers.length, best = Math.min(n, 2);
        List<Map<Integer, Integer>> table = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            Map<Integer, Integer> row = new HashMap<>();
            for (int i = 0; i < j; i++) {
                int d = numbers[j] - numbers[i];
                int length = table.get(i).getOrDefault(d, 1) + 1;
                row.put(d, length);
                best = Math.max(best, length);
            }
            table.add(row);
        }
        return best;
    }
}

int longest_arithmetic_run(vector<int>& numbers) {
