            auto it = table[i].find(d);
            int length = (it == table[i].end() ? 1 : it->second) + 1;
            table[j][d] = length;
            best = max(best, length);
        }
    }
    return best;
}

def longest_with_k_kinds(items, k):
    best = 0
    for i in range(len(items)):
        seen = set()
        for j in range(i, len(items)):
            seen.add(items[j])
            if len(seen) > k:
                break
            best = max(best, j - i + 1)
    return best

def longest_with_k_kinds(items, k):
    counts = {}
    left = 0
    best = 0
    for right, x in enumerate(items):
        counts[x] = counts.get(x, 0) + 1
        while len(counts) > k:
            y = items[left]
            counts[y] -= 1
            if counts[y] == 0:
                del counts[y]
            left += 1
        best = max(best, right - left + 1)
    return best

function longestWithKKinds(items, k) {
  const counts = new Map();
  let left = 0, best = 0;
  for (let right = 0; right < items.length; right++) {
    counts.set(items[right], (counts.get(items[right]) || 0) + 1);
    while (counts.size > k) {
      const y = items[left];
      counts.set(y, counts.get(y) - 1);
      if (counts.get(y) === 0) counts.delete(y);
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

class Solution {
    public int longestWithKKinds(int[] items, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < items.length; right++) {
            counts.merge(items[right], 1, Integer::sum);
            while (counts.size() > k) {
                int y = items[left];
                int c = counts.get(y) - 1;
                if (c == 0) counts.remove(y); else counts.put(y, c);
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

int longest_with_k_kinds(vector<int>& items, int k) {
    unordered_map<int,int> counts;
    int left = 0, best = 0;
    for (int right = 0; right < (int) items.size(); right++) {
        counts[items[right]]++;
        while ((int) counts.size() > k) {
            int y = items[left];
            if (--counts[y] == 0) counts.erase(y);
            left++;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

