def longest_valid_brackets(text):
    stack = [-1]
    best = 0
    for i, ch in enumerate(text):
        if ch == "(":
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

function longestValidBrackets(text) {
  const stack = [-1];
  let best = 0;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === "(") stack.push(i);
    else {
      stack.pop();
      if (stack.length === 0) stack.push(i);
      else best = Math.max(best, i - stack[stack.length - 1]);
    }
  }
  return best;
}

class Solution {
    public int longestValidBrackets(String text) {
        int[] stack = new int[text.length() + 1];
        int size = 0;
        stack[size++] = -1;
        int best = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == '(') stack[size++] = i;
            else {
                size--;
                if (size == 0) stack[size++] = i;
                else best = Math.max(best, i - stack[size - 1]);
            }
        }
        return best;
    }
}

