def max_capital(k, w, profits, capital):
    used = [False] * len(profits)
    for _ in range(k):
        best = -1
        for i in range(len(profits)):
            if not used[i] and capital[i] <= w and (best == -1 or profits[i] > profits[best]):
                best = i
        if best == -1:
            break
        used[best] = True
        w += profits[best]
    return w

def max_capital(k, w, profits, capital):
    import heapq

    projects = sorted(zip(capital, profits))
    heap = []
    i = 0
    for _ in range(k):
        while i < len(projects) and projects[i][0] <= w:
            heapq.heappush(heap, -projects[i][1])
            i += 1
        if not heap:
            break
        w += -heapq.heappop(heap)
    return w

function heapPush(a, x, less) {
  a.push(x);
  let i = a.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (less(a[i], a[p])) { const t = a[i]; a[i] = a[p]; a[p] = t; i = p; } else break;
  }
}
function heapPop(a, less) {
  const top = a[0];
  const last = a.pop();
  if (a.length > 0) {
    a[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < a.length && less(a[l], a[m])) m = l;
      if (r < a.length && less(a[r], a[m])) m = r;
      if (m === i) break;
      const t = a[i]; a[i] = a[m]; a[m] = t;
      i = m;
    }
  }
  return top;
}
function maxCapital(k, w, profits, capital) {
  const projects = profits.map((p, i) => [capital[i], p]).sort((a, b) => a[0] - b[0]);
  const heap = [];
  const bigger = (p, q) => p > q;
  let i = 0;
  for (let step = 0; step < k; step++) {
    while (i < projects.length && projects[i][0] <= w) { heapPush(heap, projects[i][1], bigger); i++; }
    if (heap.length === 0) break;
    w += heapPop(heap, bigger);
  }
  return w;
}

class Solution {
    public int maxCapital(int k, int w, int[] profits, int[] capital) {
        int n = profits.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (p, q) -> Integer.compare(capital[p], capital[q]));
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        long coins = w;
        int next = 0;
        for (int step = 0; step < k; step++) {
            while (next < n && capital[order[next]] <= coins) { heap.add(profits[order[next]]); next++; }
            if (heap.isEmpty()) break;
            coins += heap.poll();
        }
        return (int) coins;
    }
}

int max_capital(int k, int w, vector<int>& profits, vector<int>& capital) {
    int n = (int) profits.size();
    vector<pair<int,int>> projects;
    for (int i = 0; i < n; i++) projects.push_back({capital[i], profits[i]});
    sort(projects.begin(), projects.end());
    priority_queue<int> heap;
    long long coins = w;
    int next = 0;
    for (int step = 0; step < k; step++) {
        while (next < n && projects[next].first <= coins) { heap.push(projects[next].second); next++; }
        if (heap.empty()) break;
        coins += heap.top();
        heap.pop();
    }
    return (int) coins;
}

