    counts = {}
    total = 0
    best = 0
    for i, x in enumerate(numbers):
        counts[x] = counts.get(x, 0) + 1
        total += x
        if i >= k:
            y = numbers[i - k]
            counts[y] -= 1
            if counts[y] == 0:
                del counts[y]
            total -= y
