def max_erasure_value(numbers):
    best = 0
    n = len(numbers)
    for i in range(n):
        seen = set()
        total = 0
        for j in range(i, n):
            if numbers[j] in seen:
                break
            seen.add(numbers[j])
            total += numbers[j]
            best = max(best, total)
    return best

function maxErasureValue(numbers) {
