def max_tree_width(root):
    spans = {}

    def walk(node, depth, pos):
        if node is None:
            return
        lo, hi = spans.get(depth, (pos, pos))
        spans[depth] = (min(lo, pos), max(hi, pos))
        walk(node.left, depth + 1, 2 * pos)
        walk(node.right, depth + 1, 2 * pos + 1)

