    return max((hi - lo + 1 for lo, hi in spans.values()), default=0)

def max_tree_width(root):
    if root is None:
        return 0
    best = 0
    level = [(root, 0)]
    while level:
        best = max(best, level[-1][1] - level[0][1] + 1)
        base = level[0][1]
        nxt = []
        for node, pos in level:
            pos -= base
            if node.left is not None:
                nxt.append((node.left, 2 * pos))
            if node.right is not None:
                nxt.append((node.right, 2 * pos + 1))
        level = nxt
    return best

function maxTreeWidth(root) {
  if (root === null) return 0;
  let best = 0;
  let level = [[root, 0]];
  while (level.length > 0) {
    best = Math.max(best, level[level.length - 1][1] - level[0][1] + 1);
    const base = level[0][1];
    const next = [];
    for (const [node, p] of level) {
      const pos = p - base;
      if (node.left !== null) next.push([node.left, 2 * pos]);
      if (node.right !== null) next.push([node.right, 2 * pos + 1]);
    }
    level = next;
  }
  return best;
}

class Solution {
    public int maxTreeWidth(TreeNode root) {
        if (root == null) return 0;
        long best = 0;
        List<TreeNode> nodes = new ArrayList<>();
        List<Long> places = new ArrayList<>();
        nodes.add(root);
        places.add(0L);
        while (!nodes.isEmpty()) {
            best = Math.max(best, places.get(places.size() - 1) - places.get(0) + 1);
            long base = places.get(0);
            List<TreeNode> nextNodes = new ArrayList<>();
            List<Long> nextPlaces = new ArrayList<>();
            for (int i = 0; i < nodes.size(); i++) {
                long pos = places.get(i) - base;
                TreeNode node = nodes.get(i);
                if (node.left != null) { nextNodes.add(node.left); nextPlaces.add(2 * pos); }
                if (node.right != null) { nextNodes.add(node.right); nextPlaces.add(2 * pos + 1); }
            }
            nodes = nextNodes;
            places = nextPlaces;
        }
        return (int) best;
    }
}

