def max_unique_split(text):
    n = len(text)
    if n == 0:
        return 0
    best = 1
    for mask in range(1 << (n - 1)):
        pieces = []
        start = 0
        for i in range(n - 1):
            if (mask >> i) & 1:
                pieces.append(text[start:i + 1])
                start = i + 1
        pieces.append(text[start:])
        if len(set(pieces)) == len(pieces):
            best = max(best, len(pieces))
    return best

def max_unique_split(text):
    n = len(text)
    best = [0]
    used = set()

    def go(start, count):
        if count + (n - start) <= best[0]:
            return
        if start == n:
            best[0] = max(best[0], count)
            return
        for end in range(start + 1, n + 1):
            piece = text[start:end]
            if piece not in used:
                used.add(piece)
                go(end, count + 1)
                used.remove(piece)

    go(0, 0)
    return best[0]

function maxUniqueSplit(text) {
  const n = text.length, used = new Set();
  let best = 0;
  function go(start, count) {
    if (count + (n - start) <= best) return;
    if (start === n) { best = Math.max(best, count); return; }
    for (let end = start + 1; end <= n; end++) {
      const piece = text.slice(start, end);
      if (!used.has(piece)) {
        used.add(piece);
        go(end, count + 1);
        used.delete(piece);
      }
    }
  }
  go(0, 0);
  return best;
}

class Solution {
    private String text;
    private int best;
    private Set<String> used;

    private void go(int start, int count) {
        int n = text.length();
        if (count + (n - start) <= best) return;
        if (start == n) { best = Math.max(best, count); return; }
        for (int end = start + 1; end <= n; end++) {
            String piece = text.substring(start, end);
            if (!used.contains(piece)) {
                used.add(piece);
                go(end, count + 1);
                used.remove(piece);
            }
        }
    }

    public int maxUniqueSplit(String text) {
        this.text = text;
        this.best = 0;
        this.used = new HashSet<>();
        go(0, 0);
        return best;
    }
