        return 0
    size = max(1, (high - low) // (n - 1))
    count = (high - low) // size + 1
    mins = [None] * count
    maxs = [None] * count
    for x in numbers:
        b = (x - low) // size
        if mins[b] is None or x < mins[b]:
            mins[b] = x
        if maxs[b] is None or x > maxs[b]:
            maxs[b] = x
    previous = low
    best = 0
    for b in range(count):
        if mins[b] is None:
            continue
        best = max(best, mins[b] - previous)
        previous = maxs[b]
    return best

