function heapPush(a, x, less) {
  a.push(x);
  let i = a.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (less(a[i], a[p])) { const t = a[i]; a[i] = a[p]; a[p] = t; i = p; } else break;
  }
}
function heapPop(a, less) {
  const top = a[0];
  const last = a.pop();
  if (a.length > 0) {
    a[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < a.length && less(a[l], a[m])) m = l;
      if (r < a.length && less(a[r], a[m])) m = r;
      if (m === i) break;
      const t = a[i]; a[i] = a[m]; a[m] = t;
      i = m;
    }
  }
  return top;
}
function mergeSortedRows(rows) {
  const less = (p, q) => p[0] < q[0];
  const heap = [], out = [];
  for (let r = 0; r < rows.length; r++) if (rows[r].length > 0) heapPush(heap, [rows[r][0], r, 0], less);
  while (heap.length > 0) {
    const [value, r, c] = heapPop(heap, less);
    out.push(value);
    if (c + 1 < rows[r].length) heapPush(heap, [rows[r][c + 1], r, c + 1], less);
  }
  return out;
}

class Solution {
    public int[] mergeSortedRows(int[][] rows) {
        int total = 0;
        for (int[] row : rows) total += row.length;
        PriorityQueue<int[]> heap = new PriorityQueue<>((p, q) -> Integer.compare(p[0], q[0]));
        for (int r = 0; r < rows.length; r++) if (rows[r].length > 0) heap.add(new int[]{rows[r][0], r, 0});
        int[] out = new int[total];
        int size = 0;
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            out[size++] = top[0];
            int r = top[1], c = top[2];
            if (c + 1 < rows[r].length) heap.add(new int[]{rows[r][c + 1], r, c + 1});
        }
        return out;
    }
}

vector<int> merge_sorted_rows(vector<vector<int>>& rows) {
