def cheapest_route(n, roads, start, end):
    # Bellman-Ford: relax every road n - 1 times
    inf = float("inf")
    dist = [inf] * n
    dist[start] = 0
    for _ in range(n - 1):
        for u, v, w in roads:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return -1 if dist[end] == inf else dist[end]

def cheapest_route(n, roads, start, end):
    import heapq

    adjacent = [[] for _ in range(n)]
    for u, v, w in roads:
        adjacent[u].append((v, w))
    dist = [None] * n
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == end:
            return d
        for v, w in adjacent[u]:
            nd = d + w
            if dist[v] is None or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

function cheapestRoute(n, roads, start, end) {
  const INF = Infinity;
  const dist = new Array(n).fill(INF);
  const done = new Array(n).fill(false);
  dist[start] = 0;
  for (let round = 0; round < n; round++) {
    let u = -1;
    for (let i = 0; i < n; i++) if (!done[i] && (u === -1 || dist[i] < dist[u])) u = i;
    if (u === -1 || dist[u] === INF) break;
    done[u] = true;
    for (const [from, to, cost] of roads) if (from === u && dist[u] + cost < dist[to]) dist[to] = dist[u] + cost;
  }
  return dist[end] === INF ? -1 : dist[end];
}

class Solution {
    public int cheapestRoute(int n, int[][] roads, int start, int end) {
        List<List<int[]>> adjacent = new ArrayList<>();
        for (int i = 0; i < n; i++) adjacent.add(new ArrayList<>());
        for (int[] r : roads) adjacent.get(r[0]).add(new int[]{r[1], r[2]});
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        heap.add(new long[]{0, start});
        while (!heap.isEmpty()) {
            long[] top = heap.poll();
            int u = (int) top[1];
            if (top[0] > dist[u]) continue;
            if (u == end) return (int) top[0];
            for (int[] edge : adjacent.get(u)) {
                long nd = top[0] + edge[1];
                if (nd < dist[edge[0]]) { dist[edge[0]] = nd; heap.add(new long[]{nd, edge[0]}); }
            }
        }
        return -1;
    }
}

int cheapest_route(int n, vector<vector<int>>& roads, int start, int end) {
    vector<vector<pair<int, int>>> adjacent(n);
    for (auto& r : roads) adjacent[r[0]].push_back({r[1], r[2]});
    const long long INF = LLONG_MAX / 4;
    vector<long long> dist(n, INF);
    dist[start] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> heap;
    heap.push({0, start});
    while (!heap.empty()) {
        auto [d, u] = heap.top();
        heap.pop();
        if (d > dist[u]) continue;
        if (u == end) return (int) d;
        for (auto& edge : adjacent[u]) {
            long long nd = d + edge.second;
            if (nd < dist[edge.first]) { dist[edge.first] = nd; heap.push({nd, edge.first}); }
        }
    }
    return -1;
}

def min_cost_climb(cost):
    n = len(cost)

    def go(i):  # cheapest cost to the top when about to step on step i
        if i >= n:
            return 0
        return cost[i] + min(go(i + 1), go(i + 2))

    return min(go(0), go(1))

def min_cost_climb(cost):
    n = len(cost)
    best = [0] * (n + 1)
    for i in range(2, n + 1):
        best[i] = min(best[i - 1] + cost[i - 1], best[i - 2] + cost[i - 2])
    return best[n]

def min_cost_climb(cost):
    prev2 = prev1 = 0
    for i in range(2, len(cost) + 1):
        prev2, prev1 = prev1, min(prev1 + cost[i - 1], prev2 + cost[i - 2])
    return prev1

function minCostClimb(cost) {
  let prev2 = 0, prev1 = 0;
  for (let i = 2; i <= cost.length; i++) {
    const current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
    prev2 = prev1;
    prev1 = current;
  }
  return prev1;
}

class Solution {
    public int minCostClimb(int[] cost) {
        int prev2 = 0, prev1 = 0;
        for (int i = 2; i <= cost.length; i++) {
            int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
            prev2 = prev1;
            prev1 = current;
        }
        return prev1;
    }
}

int min_cost_climb(vector<int>& cost) {
    int prev2 = 0, prev1 = 0;
    for (int i = 2; i <= (int) cost.size(); i++) {
        int current = min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

def tree_min_depth(root):
    def depth(node):
        if node is None:
            return 0
        if node.left is None:
            return 1 + depth(node.right)
        if node.right is None:
            return 1 + depth(node.left)
        return 1 + min(depth(node.left), depth(node.right))

    return depth(root)

def tree_min_depth(root):
    if root is None:
        return 0
    queue = [(root, 1)]
    for node, level in queue:
        if node.left is None and node.right is None:
            return level
        if node.left is not None:
            queue.append((node.left, level + 1))
        if node.right is not None:
            queue.append((node.right, level + 1))

function treeMinDepth(root) {
  if (root === null) return 0;
  const queue = [[root, 1]];
  for (let head = 0; head < queue.length; head++) {
    const [node, level] = queue[head];
    if (node.left === null && node.right === null) return level;
    if (node.left !== null) queue.push([node.left, level + 1]);
    if (node.right !== null) queue.push([node.right, level + 1]);
  }
  return 0;
}

class Solution {
    public int treeMinDepth(TreeNode root) {
        if (root == null) return 0;
        ArrayDeque<TreeNode> nodes = new ArrayDeque<>();
        ArrayDeque<Integer> levels = new ArrayDeque<>();
        nodes.add(root);
        levels.add(1);
        while (!nodes.isEmpty()) {
            TreeNode node = nodes.poll();
            int level = levels.poll();
            if (node.left == null && node.right == null) return level;
            if (node.left != null) { nodes.add(node.left); levels.add(level + 1); }
            if (node.right != null) { nodes.add(node.right); levels.add(level + 1); }
        }
        return 0;
    }
}

int tree_min_depth(TreeNode* root) {
    if (root == nullptr) return 0;
    queue<pair<TreeNode*, int>> q;
    q.push({root, 1});
    while (!q.empty()) {
        pair<TreeNode*, int> cur = q.front();
        q.pop();
        TreeNode* node = cur.first;
        if (node->left == nullptr && node->right == nullptr) return cur.second;
        if (node->left != nullptr) q.push({node->left, cur.second + 1});
        if (node->right != nullptr) q.push({node->right, cur.second + 1});
    }
    return 0;
}

def min_falling_path_sum(matrix):
    rows, cols = len(matrix), len(matrix[0])

    def go(r, c):
        if r == rows - 1:
            return matrix[r][c]
        options = [go(r + 1, c + d) for d in (-1, 0, 1) if 0 <= c + d < cols]
        return matrix[r][c] + min(options)

    return min(go(0, c) for c in range(cols))

def min_falling_path_sum(matrix):
    rows, cols = len(matrix), len(matrix[0])
    best = list(matrix[0])
    for r in range(1, rows):
        new = []
        for c in range(cols):
            new.append(matrix[r][c] + min(best[c + d] for d in (-1, 0, 1) if 0 <= c + d < cols))
        best = new
    return min(best)

function minFallingPathSum(matrix) {
  const rows = matrix.length, cols = matrix[0].length;
  let best = matrix[0].slice();
  for (let r = 1; r < rows; r++) {
    const next = [];
    for (let c = 0; c < cols; c++) {
      let low = best[c];
      if (c > 0) low = Math.min(low, best[c - 1]);
      if (c + 1 < cols) low = Math.min(low, best[c + 1]);
      next.push(matrix[r][c] + low);
    }
    best = next;
  }
  return Math.min(...best);
}

class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int rows = matrix.length, cols = matrix[0].length;
        int[] best = matrix[0].clone();
        for (int r = 1; r < rows; r++) {
            int[] next = new int[cols];
            for (int c = 0; c < cols; c++) {
                int low = best[c];
                if (c > 0) low = Math.min(low, best[c - 1]);
                if (c + 1 < cols) low = Math.min(low, best[c + 1]);
                next[c] = matrix[r][c] + low;
            }
            best = next;
        }
        int answer = best[0];
        for (int v : best) answer = Math.min(answer, v);
        return answer;
    }
}

