    }
    return *min_element(best.begin(), best.end());
}

def min_height_roots(n, edges):
    adjacent = [[] for _ in range(n)]
    for a, b in edges:
        adjacent[a].append(b)
        adjacent[b].append(a)

    def height(root):
        depth = {root: 0}
        queue = [root]
        for u in queue:
            for v in adjacent[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    queue.append(v)
        return max(depth.values())

    heights = [height(r) for r in range(n)]
    best = min(heights)
    return [r for r in range(n) if heights[r] == best]

def min_height_roots(n, edges):
    if n <= 2:
        return list(range(n))
    adjacent = [[] for _ in range(n)]
    for a, b in edges:
        adjacent[a].append(b)
        adjacent[b].append(a)
    degree = [len(adjacent[v]) for v in range(n)]
    leaves = [v for v in range(n) if degree[v] == 1]
    remaining = n
    while remaining > 2:
        remaining -= len(leaves)
        new_leaves = []
        for leaf in leaves:
            for v in adjacent[leaf]:
                degree[v] -= 1
                if degree[v] == 1:
                    new_leaves.append(v)
        leaves = new_leaves
    return sorted(leaves)

function minHeightRoots(n, edges) {
  if (n <= 2) { const all = []; for (let i = 0; i < n; i++) all.push(i); return all; }
  const adjacent = [];
  for (let i = 0; i < n; i++) adjacent.push([]);
  for (const [a, b] of edges) { adjacent[a].push(b); adjacent[b].push(a); }
  const degree = adjacent.map((list) => list.length);
  let leaves = [];
  for (let v = 0; v < n; v++) if (degree[v] === 1) leaves.push(v);
  let remaining = n;
  while (remaining > 2) {
    remaining -= leaves.length;
    const next = [];
    for (const leaf of leaves) {
      for (const v of adjacent[leaf]) {
        degree[v]--;
        if (degree[v] === 1) next.push(v);
      }
    }
    leaves = next;
  }
  return leaves.sort((p, q) => p - q);
}

class Solution {
    public int[] minHeightRoots(int n, int[][] edges) {
        if (n <= 2) {
            int[] all = new int[n];
            for (int i = 0; i < n; i++) all[i] = i;
            return all;
        }
        List<List<Integer>> adjacent = new ArrayList<>();
        for (int i = 0; i < n; i++) adjacent.add(new ArrayList<>());
        for (int[] e : edges) { adjacent.get(e[0]).add(e[1]); adjacent.get(e[1]).add(e[0]); }
        int[] degree = new int[n];
        List<Integer> leaves = new ArrayList<>();
        for (int v = 0; v < n; v++) { degree[v] = adjacent.get(v).size(); if (degree[v] == 1) leaves.add(v); }
        int remaining = n;
        while (remaining > 2) {
            remaining -= leaves.size();
            List<Integer> next = new ArrayList<>();
            for (int leaf : leaves) {
                for (int v : adjacent.get(leaf)) {
                    degree[v]--;
                    if (degree[v] == 1) next.add(v);
                }
            }
            leaves = next;
        }
        Collections.sort(leaves);
        int[] result = new int[leaves.size()];
        for (int i = 0; i < result.length; i++) result[i] = leaves.get(i);
        return result;
    }
}

vector<int> min_height_roots(int n, vector<vector<int>>& edges) {
    if (n <= 2) {
        vector<int> all;
        for (int i = 0; i < n; i++) all.push_back(i);
        return all;
    }
    vector<vector<int>> adjacent(n);
    for (auto& e : edges) { adjacent[e[0]].push_back(e[1]); adjacent[e[1]].push_back(e[0]); }
    vector<int> degree(n), leaves;
    for (int v = 0; v < n; v++) { degree[v] = (int) adjacent[v].size(); if (degree[v] == 1) leaves.push_back(v); }
    int remaining = n;
    while (remaining > 2) {
        remaining -= (int) leaves.size();
        vector<int> next;
        for (int leaf : leaves) {
            for (int v : adjacent[leaf]) {
                degree[v]--;
                if (degree[v] == 1) next.push_back(v);
            }
        }
        leaves = next;
    }
    sort(leaves.begin(), leaves.end());
    return leaves;
}

def min_index_sum_common(first, second):
    best = -1
    for i, x in enumerate(first):
        for j, y in enumerate(second):
            if x == y and (best == -1 or i + j < best):
                best = i + j
    return best

def min_index_sum_common(first, second):
    position = {x: i for i, x in enumerate(first)}
    best = -1
    for j, x in enumerate(second):
        if x in position:
            s = position[x] + j
            if best == -1 or s < best:
                best = s
    return best

function minIndexSumCommon(first, second) {
  const position = new Map();
  first.forEach((x, i) => position.set(x, i));
  let best = -1;
  for (let j = 0; j < second.length; j++) {
    if (position.has(second[j])) {
      const s = position.get(second[j]) + j;
      if (best === -1 || s < best) best = s;
    }
  }
  return best;
}

class Solution {
    public int minIndexSumCommon(int[] first, int[] second) {
        Map<Integer, Integer> position = new HashMap<>();
        for (int i = 0; i < first.length; i++) position.put(first[i], i);
        int best = -1;
        for (int j = 0; j < second.length; j++) {
            Integer i = position.get(second[j]);
            if (i != null) {
                int s = i + j;
                if (best == -1 || s < best) best = s;
            }
        }
        return best;
    }
}

int min_index_sum_common(vector<int>& first, vector<int>& second) {
    unordered_map<int, int> position;
    for (int i = 0; i < (int) first.size(); i++) position[first[i]] = i;
    int best = -1;
    for (int j = 0; j < (int) second.size(); j++) {
        auto it = position.find(second[j]);
        if (it != position.end()) {
            int s = it->second + j;
            if (best == -1 || s < best) best = s;
        }
    }
    return best;
}

def min_jumps(jumps):
    n = len(jumps)
    best = [None] * n
    best[0] = 0
    for i in range(n):
        if best[i] is None:
            continue
        for step in range(1, jumps[i] + 1):
            j = i + step
            if j < n and (best[j] is None or best[i] + 1 < best[j]):
                best[j] = best[i] + 1
    return best[n - 1]

def min_jumps(jumps):
    jumps_used = range_end = farthest = 0
    for i in range(len(jumps) - 1):
        farthest = max(farthest, i + jumps[i])
        if i == range_end:
            jumps_used += 1
            range_end = farthest
    return jumps_used

function minJumps(jumps) {
  let used = 0, rangeEnd = 0, farthest = 0;
  for (let i = 0; i < jumps.length - 1; i++) {
    farthest = Math.max(farthest, i + jumps[i]);
    if (i === rangeEnd) { used++; rangeEnd = farthest; }
  }
  return used;
}

class Solution {
    public int minJumps(int[] jumps) {
        int used = 0, rangeEnd = 0, farthest = 0;
        for (int i = 0; i < jumps.length - 1; i++) {
            farthest = Math.max(farthest, i + jumps[i]);
            if (i == rangeEnd) { used++; rangeEnd = farthest; }
        }
        return used;
    }
}

int min_jumps(vector<int>& jumps) {
    int used = 0, range_end = 0, farthest = 0;
    for (int i = 0; i + 1 < (int) jumps.size(); i++) {
        farthest = max(farthest, i + jumps[i]);
        if (i == range_end) { used++; range_end = farthest; }
    }
    return used;
}

def min_knight_moves(size, start_row, start_col, target_row, target_col):
    moves = ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2))
    INF = 10 ** 9
    dist = [[INF] * size for _ in range(size)]
    dist[start_row][start_col] = 0
    changed = True
    while changed:
        changed = False
        for r in range(size):
            for c in range(size):
                if dist[r][c] == INF:
                    continue
                for dr, dc in moves:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < size and 0 <= nc < size and dist[r][c] + 1 < dist[nr][nc]:
                        dist[nr][nc] = dist[r][c] + 1
                        changed = True
    return -1 if dist[target_row][target_col] == INF else dist[target_row][target_col]

def min_knight_moves(size, start_row, start_col, target_row, target_col):
    from collections import deque

    moves = ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2))
    dist = [[-1] * size for _ in range(size)]
    dist[start_row][start_col] = 0
    queue = deque([(start_row, start_col)])
    while queue:
        r, c = queue.popleft()
        if r == target_row and c == target_col:
            return dist[r][c]
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < size and 0 <= nc < size and dist[nr][nc] < 0:
                dist[nr][nc] = dist[r][c] + 1
                queue.append((nr, nc))
    return -1

function minKnightMoves(size, startRow, startCol, targetRow, targetCol) {
  const dr = [1, 2, 2, 1, -1, -2, -2, -1], dc = [2, 1, -1, -2, -2, -1, 1, 2];
  const dist = [];
  for (let r = 0; r < size; r++) dist.push(new Array(size).fill(-1));
  dist[startRow][startCol] = 0;
  const queue = [[startRow, startCol]];
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    if (r === targetRow && c === targetCol) return dist[r][c];
    for (let m = 0; m < 8; m++) {
      const nr = r + dr[m], nc = c + dc[m];
      if (nr >= 0 && nr < size && nc >= 0 && nc < size && dist[nr][nc] < 0) {
        dist[nr][nc] = dist[r][c] + 1;
        queue.push([nr, nc]);
      }
    }
  }
  return -1;
}

class Solution {
    public int minKnightMoves(int size, int startRow, int startCol, int targetRow, int targetCol) {
        int[] dr = {1, 2, 2, 1, -1, -2, -2, -1}, dc = {2, 1, -1, -2, -2, -1, 1, 2};
        int[][] dist = new int[size][size];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[startRow][startCol] = 0;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startRow, startCol});
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1];
            if (r == targetRow && c == targetCol) return dist[r][c];
            for (int m = 0; m < 8; m++) {
                int nr = r + dr[m], nc = c + dc[m];
                if (nr >= 0 && nr < size && nc >= 0 && nc < size && dist[nr][nc] < 0) {
                    dist[nr][nc] = dist[r][c] + 1;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return -1;
    }
}

int min_knight_moves(int size, int start_row, int start_col, int target_row, int target_col) {
    int dr[8] = {1, 2, 2, 1, -1, -2, -2, -1}, dc[8] = {2, 1, -1, -2, -2, -1, 1, 2};
    vector<vector<int>> dist(size, vector<int>(size, -1));
    dist[start_row][start_col] = 0;
    queue<pair<int,int>> q;
    q.push({start_row, start_col});
    while (!q.empty()) {
        pair<int,int> cur = q.front();
        q.pop();
        int r = cur.first, c = cur.second;
        if (r == target_row && c == target_col) return dist[r][c];
        for (int m = 0; m < 8; m++) {
            int nr = r + dr[m], nc = c + dc[m];
            if (nr >= 0 && nr < size && nc >= 0 && nc < size && dist[nr][nc] < 0) {
                dist[nr][nc] = dist[r][c] + 1;
                q.push({nr, nc});
            }
        }
    }
    return -1;
}

def min_max_pair_sum(numbers):
    def best(items):
        if not items:
            return 0
        first = items[0]
        result = None
        for i in range(1, len(items)):
            rest = items[1:i] + items[i + 1:]
            cost = max(first + items[i], best(rest))
            if result is None or cost < result:
                result = cost
        return result

    return best(list(numbers))

function minMaxPairSum(numbers) {
  const a = numbers.slice().sort((p, q) => p - q), n = a.length;
  let result = 0;
  for (let i = 0; i < Math.floor(n / 2); i++) result = Math.max(result, a[i] + a[n - 1 - i]);
  return result;
}

class Solution {
    public int minMaxPairSum(int[] numbers) {
        int[] a = numbers.clone();
        Arrays.sort(a);
        int n = a.length, result = 0;
        for (int i = 0; i < n / 2; i++) result = Math.max(result, a[i] + a[n - 1 - i]);
        return result;
    }
}

int min_max_pair_sum(vector<int>& numbers) {
    vector<int> a = numbers;
    sort(a.begin(), a.end());
    int n = (int) a.size(), result = 0;
    for (int i = 0; i < n / 2; i++) result = max(result, a[i] + a[n - 1 - i]);
    return result;
}

def min_palindrome_cuts(text):
    n = len(text)
    best = n - 1
    for mask in range(1 << (n - 1)):
        start = 0
        ok = True
        for i in range(n):
            if i == n - 1 or (mask >> i) & 1:
                piece = text[start:i + 1]
                if piece != piece[::-1]:
                    ok = False
                    break
                start = i + 1
        if ok:
            best = min(best, bin(mask).count("1"))
    return best

def min_palindrome_cuts(text):
    n = len(text)
    memo = {}

    def go(i):
        if i == n:
            return -1
        if i in memo:
            return memo[i]
        best = n
        for j in range(i, n):
            piece = text[i:j + 1]
            if piece == piece[::-1]:
                best = min(best, go(j + 1) + 1)
        memo[i] = best
        return best

    return go(0)

def min_palindrome_cuts(text):
    n = len(text)
    cuts = [i - 1 for i in range(n + 1)]
    for center in range(n):
        for left, right in ((center, center), (center, center + 1)):
            while left >= 0 and right < n and text[left] == text[right]:
                cuts[right + 1] = min(cuts[right + 1], cuts[left] + 1)
                left -= 1
                right += 1
    return cuts[n]

function minPalindromeCuts(text) {
  const n = text.length;
  const cuts = [];
  for (let i = 0; i <= n; i++) cuts.push(i - 1);
  for (let center = 0; center < n; center++) {
    for (let side = 0; side < 2; side++) {
      let left = center, right = center + side;
      while (left >= 0 && right < n && text[left] === text[right]) {
        cuts[right + 1] = Math.min(cuts[right + 1], cuts[left] + 1);
        left--;
        right++;
      }
    }
  }
  return cuts[n];
}

class Solution {
