def min_refuel_stops(target, start_fuel, stations):
    n = len(stations)
    dp = [start_fuel] + [0] * n
    for i, (pos, fuel) in enumerate(stations):
        for t in range(i, -1, -1):
            if dp[t] >= pos:
                dp[t + 1] = max(dp[t + 1], dp[t] + fuel)
    for t in range(n + 1):
        if dp[t] >= target:
            return t
    return -1

function minRefuelStops(target, startFuel, stations) {
  const avail = [];
  let reach = startFuel, stops = 0, i = 0;
  while (reach < target) {
    while (i < stations.length && stations[i][0] <= reach) { avail.push(stations[i][1]); i++; }
    if (avail.length === 0) return -1;
    let best = 0;
    for (let j = 1; j < avail.length; j++) if (avail[j] > avail[best]) best = j;
    reach += avail[best];
    avail.splice(best, 1);
    stops++;
  }
  return stops;
}

class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        long reach = startFuel;
        int stops = 0, i = 0;
        while (reach < target) {
            while (i < stations.length && stations[i][0] <= reach) { heap.add((long) stations[i][1]); i++; }
            if (heap.isEmpty()) return -1;
            reach += heap.poll();
            stops++;
        }
        return stops;
    }
}

