def min_spanning_cost(nodes, roads):
    from itertools import combinations

    if nodes == 1:
        return 0
    best = -1
    for chosen in combinations(roads, nodes - 1):
        parent = list(range(nodes))
        joined = 0
        for a, b, cost in chosen:
            ra, rb = a, b
            while parent[ra] != ra:
                ra = parent[ra]
            while parent[rb] != rb:
                rb = parent[rb]
            if ra != rb:
                parent[ra] = rb
                joined += 1
        if joined == nodes - 1:
            total = sum(c for _, _, c in chosen)
            if best == -1 or total < best:
                best = total
    return best

