        rows[r] |= bit; cols[c] |= bit; boxes[Math.floor(r / 2) * 2 + Math.floor(c / 2)] |= bit;
      } else empty.push([r, c]);
    }
  }
  function fill(i) {
    if (i === empty.length) return 1;
    const [r, c] = empty[i];
    const b = Math.floor(r / 2) * 2 + Math.floor(c / 2);
    let total = 0;
    for (let v = 1; v <= 4; v++) {
      const bit = 1 << v;
      if (!((rows[r] & bit) || (cols[c] & bit) || (boxes[b] & bit))) {
        rows[r] |= bit; cols[c] |= bit; boxes[b] |= bit;
        total += fill(i + 1);
        rows[r] ^= bit; cols[c] ^= bit; boxes[b] ^= bit;
      }
    }
    return total;
  }
  return fill(0);
}

class Solution {
    private int[] rows = new int[4], cols = new int[4], boxes = new int[4];
    private int[][] empty;
    private int emptyCount;

    private int fill(int i) {
        if (i == emptyCount) return 1;
        int r = empty[i][0], c = empty[i][1];
        int b = (r / 2) * 2 + c / 2;
        int total = 0;
        for (int v = 1; v <= 4; v++) {
            int bit = 1 << v;
            if ((rows[r] & bit) == 0 && (cols[c] & bit) == 0 && (boxes[b] & bit) == 0) {
                rows[r] |= bit; cols[c] |= bit; boxes[b] |= bit;
                total += fill(i + 1);
                rows[r] ^= bit; cols[c] ^= bit; boxes[b] ^= bit;
            }
        }
        return total;
    }

    public int miniSudokuCount(int[][] board) {
        rows = new int[4]; cols = new int[4]; boxes = new int[4];
        empty = new int[16][2];
        emptyCount = 0;
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
