int sudoku_fill(int i, vector<pair<int,int>>& empty, int rows[4], int cols[4], int boxes[4]) {
    if (i == (int) empty.size()) return 1;
    int r = empty[i].first, c = empty[i].second;
    int b = (r / 2) * 2 + c / 2;
    int total = 0;
    for (int v = 1; v <= 4; v++) {
        int bit = 1 << v;
        if ((rows[r] & bit) == 0 && (cols[c] & bit) == 0 && (boxes[b] & bit) == 0) {
            rows[r] |= bit; cols[c] |= bit; boxes[b] |= bit;
            total += sudoku_fill(i + 1, empty, rows, cols, boxes);
            rows[r] ^= bit; cols[c] ^= bit; boxes[b] ^= bit;
        }
    }
    return total;
}

int mini_sudoku_count(vector<vector<int>>& board) {
    int rows[4] = {0, 0, 0, 0}, cols[4] = {0, 0, 0, 0}, boxes[4] = {0, 0, 0, 0};
    vector<pair<int,int>> empty;
    for (int r = 0; r < 4; r++) {
        for (int c = 0; c < 4; c++) {
            int v = board[r][c];
            if (v != 0) {
                int bit = 1 << v;
                rows[r] |= bit; cols[c] |= bit; boxes[(r / 2) * 2 + c / 2] |= bit;
            } else {
                empty.push_back({r, c});
            }
        }
    }
    return sudoku_fill(0, empty, rows, cols, boxes);
}

def min_swaps_to_sort(numbers):
    items = list(numbers)
    swaps = 0
    for i in range(len(items)):
        smallest = i
        for j in range(i + 1, len(items)):
            if items[j] < items[smallest]:
                smallest = j
        if smallest != i:
            items[i], items[smallest] = items[smallest], items[i]
            swaps += 1
    return swaps

def min_swaps_to_sort(numbers):
    n = len(numbers)
    order = sorted(range(n), key=lambda i: numbers[i])
    target = [0] * n
    for rank, i in enumerate(order):
        target[i] = rank
    visited = [False] * n
    cycles = 0
    for i in range(n):
        if not visited[i]:
            cycles += 1
            j = i
            while not visited[j]:
                visited[j] = True
                j = target[j]
    return n - cycles

function minSwapsToSort(numbers) {
  const n = numbers.length;
  const order = [];
  for (let i = 0; i < n; i++) order.push(i);
  order.sort((a, b) => numbers[a] - numbers[b]);
  const target = new Array(n).fill(0);
  for (let rank = 0; rank < n; rank++) target[order[rank]] = rank;
  const visited = new Array(n).fill(false);
  let cycles = 0;
  for (let i = 0; i < n; i++) {
    if (!visited[i]) {
      cycles++;
      let j = i;
      while (!visited[j]) { visited[j] = true; j = target[j]; }
    }
  }
  return n - cycles;
}

class Solution {
    public int minSwapsToSort(int[] numbers) {
        int n = numbers.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(numbers[a], numbers[b]));
        int[] target = new int[n];
        for (int rank = 0; rank < n; rank++) target[order[rank]] = rank;
        boolean[] visited = new boolean[n];
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                cycles++;
                int j = i;
                while (!visited[j]) { visited[j] = true; j = target[j]; }
            }
        }
        return n - cycles;
    }
}

int min_swaps_to_sort(vector<int>& numbers) {
    int n = (int) numbers.size();
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int a, int b) { return numbers[a] < numbers[b]; });
    vector<int> target(n);
    for (int rank = 0; rank < n; rank++) target[order[rank]] = rank;
    vector<char> visited(n, 0);
    int cycles = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            cycles++;
            int j = i;
            while (!visited[j]) { visited[j] = 1; j = target[j]; }
        }
    }
    return n - cycles;
}

def is_mirror(root):
    def flipped(node):
        return None if node is None else (node.val, flipped(node.right), flipped(node.left))

    def plain(node):
        return None if node is None else (node.val, plain(node.left), plain(node.right))

    return root is None or plain(root.left) == flipped(root.right)

def is_mirror(root):
    def same(a, b):
        if a is None or b is None:
            return a is b
        return a.val == b.val and same(a.left, b.right) and same(a.right, b.left)

    return root is None or same(root.left, root.right)

function isMirror(root) {
  function same(a, b) {
    if (a === null || b === null) return a === b;
    return a.val === b.val && same(a.left, b.right) && same(a.right, b.left);
  }
  return root === null || same(root.left, root.right);
}

class Solution {
    private boolean same(TreeNode a, TreeNode b) {
        if (a == null || b == null) return a == b;
        return a.val == b.val && same(a.left, b.right) && same(a.right, b.left);
    }

    public boolean isMirror(TreeNode root) {
        return root == null || same(root.left, root.right);
    }
}

bool mirror_same(TreeNode* a, TreeNode* b) {
    if (a == nullptr || b == nullptr) return a == b;
    return a->val == b->val && mirror_same(a->left, b->right) && mirror_same(a->right, b->left);
}

bool is_mirror(TreeNode* root) {
    return root == nullptr || mirror_same(root->left, root->right);
}

