def largest_monotone(number):
    x = number
    while x > 0:
        s = str(x)
        if all(s[i] <= s[i + 1] for i in range(len(s) - 1)):
            return x
        x -= 1
    return 0

def largest_monotone(number):
    s = str(number)

    def rising(t):
        return all(t[i] <= t[i + 1] for i in range(len(t) - 1))

    if rising(s):
        return number
    best = 0
    for i in range(len(s)):
        if s[i] == "0":
            continue
        candidate = s[:i] + str(int(s[i]) - 1) + "9" * (len(s) - i - 1)
        if rising(candidate):
            best = max(best, int(candidate))
    return best

def largest_monotone(number):
    digits = [int(c) for c in str(number)]
    mark = len(digits)
    for i in range(len(digits) - 1, 0, -1):
        if digits[i - 1] > digits[i]:
            digits[i - 1] -= 1
            mark = i
    for i in range(mark, len(digits)):
        digits[i] = 9
    return int("".join(str(d) for d in digits))

function largestMonotone(number) {
  const digits = String(number).split("").map(Number);
  let mark = digits.length;
  for (let i = digits.length - 1; i > 0; i--) {
    if (digits[i - 1] > digits[i]) { digits[i - 1]--; mark = i; }
  }
  for (let i = mark; i < digits.length; i++) digits[i] = 9;
  return Number(digits.join(""));
}

class Solution {
