def max_load_units(boxes, truck_size):
    every_box = []
    for count, units in boxes:
        every_box += [units] * count
    every_box.sort(reverse=True)
    return sum(every_box[:truck_size])

def max_load_units(boxes, truck_size):
    room = truck_size
    total = 0
    for count, units in sorted(boxes, key=lambda kind: -kind[1]):
        take = min(count, room)
        total += take * units
        room -= take
        if room == 0:
            break
    return total

function maxLoadUnits(boxes, truckSize) {
  let room = truckSize, total = 0;
  const sorted = boxes.slice().sort((a, b) => b[1] - a[1]);
  for (const [count, units] of sorted) {
    if (room === 0) break;
    const take = Math.min(count, room);
    total += take * units;
    room -= take;
  }
  return total;
}

class Solution {
    public int maxLoadUnits(int[][] boxes, int truckSize) {
        int[][] sorted = boxes.clone();
        Arrays.sort(sorted, (a, b) -> Integer.compare(b[1], a[1]));
        int room = truckSize;
        long total = 0;
        for (int[] kind : sorted) {
            if (room == 0) break;
            int take = Math.min(kind[0], room);
            total += (long) take * kind[1];
            room -= take;
        }
        return (int) total;
    }
}

int max_load_units(vector<vector<int>>& boxes, int truck_size) {
    vector<vector<int>> sorted_boxes = boxes;
    sort(sorted_boxes.begin(), sorted_boxes.end(), [](const vector<int>& a, const vector<int>& b) { return a[1] > b[1]; });
    int room = truck_size;
    long long total = 0;
    for (auto& kind : sorted_boxes) {
        if (room == 0) break;
        int take = min(kind[0], room);
        total += (long long) take * kind[1];
        room -= take;
    }
    return (int) total;
}

def peak_index(heights):
    lo, hi = 0, len(heights) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if heights[mid] < heights[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo

function peakIndex(heights) {
