def has_multiple_run(numbers, k):
    n = len(numbers)
    for i in range(n):
        total = numbers[i]
        for j in range(i + 1, n):
            total += numbers[j]
            if total % k == 0:
                return True
    return False

def has_multiple_run(numbers, k):
    first = {0: -1}
    total = 0
    for i, x in enumerate(numbers):
        total = (total + x) % k
        if total in first:
            if i - first[total] >= 2:
                return True
        else:
            first[total] = i
    return False

function hasMultipleRun(numbers, k) {
  const first = new Map([[0, -1]]);
  let total = 0;
  for (let i = 0; i < numbers.length; i++) {
    total = (total + numbers[i]) % k;
    if (first.has(total)) {
      if (i - first.get(total) >= 2) return true;
    } else {
      first.set(total, i);
    }
  }
  return false;
}

class Solution {
    public boolean hasMultipleRun(int[] numbers, int k) {
        Map<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);
        long total = 0;
        for (int i = 0; i < numbers.length; i++) {
            total = (total + numbers[i]) % k;
            Integer seen = first.get(total);
            if (seen != null) {
                if (i - seen >= 2) return true;
            } else {
                first.put(total, i);
            }
        }
        return false;
    }
}

