}

def multiply_digits(first, second):
    if first == "0" or second == "0":
        return "0"
    result = [0] * (len(first) + len(second))
    for i in range(len(first) - 1, -1, -1):
        for j in range(len(second) - 1, -1, -1):
            total = int(first[i]) * int(second[j]) + result[i + j + 1]
            result[i + j + 1] = total % 10
            result[i + j] += total // 10
    start = 0
    while start < len(result) - 1 and result[start] == 0:
        start += 1
    return "".join(str(d) for d in result[start:])

function multiplyDigits(first, second) {
  if (first === "0" || second === "0") return "0";
  const result = new Array(first.length + second.length).fill(0);
  for (let i = first.length - 1; i >= 0; i--) {
    for (let j = second.length - 1; j >= 0; j--) {
      const total = (first.charCodeAt(i) - 48) * (second.charCodeAt(j) - 48) + result[i + j + 1];
      result[i + j + 1] = total % 10;
      result[i + j] += Math.floor(total / 10);
    }
  }
  let start = 0;
  while (start < result.length - 1 && result[start] === 0) start++;
  return result.slice(start).join("");
}

class Solution {
    public String multiplyDigits(String first, String second) {
        if (first.equals("0") || second.equals("0")) return "0";
        int[] result = new int[first.length() + second.length()];
        for (int i = first.length() - 1; i >= 0; i--) {
            for (int j = second.length() - 1; j >= 0; j--) {
                int total = (first.charAt(i) - '0') * (second.charAt(j) - '0') + result[i + j + 1];
                result[i + j + 1] = total % 10;
                result[i + j] += total / 10;
            }
        }
        int start = 0;
        while (start < result.length - 1 && result[start] == 0) start++;
        StringBuilder out = new StringBuilder();
        for (int k = start; k < result.length; k++) out.append(result[k]);
        return out.toString();
    }
}

string multiply_digits(string first, string second) {
    if (first == "0" || second == "0") return "0";
    vector<int> result(first.size() + second.size(), 0);
    for (int i = (int) first.size() - 1; i >= 0; i--) {
        for (int j = (int) second.size() - 1; j >= 0; j--) {
            int total = (first[i] - '0') * (second[j] - '0') + result[i + j + 1];
            result[i + j + 1] = total % 10;
            result[i + j] += total / 10;
        }
    }
    size_t start = 0;
    while (start + 1 < result.size() && result[start] == 0) start++;
    string out;
    for (size_t k = start; k < result.size(); k++) out += (char) ('0' + result[k]);
    return out;
}

def count_queens(n):
    cols = []

    def place(row):
        if row == n:
            return 1
        total = 0
        for c in range(n):
            if all(c != cols[r] and abs(c - cols[r]) != row - r for r in range(row)):
                cols.append(c)
                total += place(row + 1)
                cols.pop()
        return total

    return place(0)

def count_queens(n):
    full = (1 << n) - 1

    def place(cols, diag, anti):
        if cols == full:
            return 1
        total = 0
        free = full & ~(cols | diag | anti)
        while free:
            bit = free & -free
            free -= bit
            total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1)
        return total

    return place(0, 0, 0)

function countQueens(n) {
  const full = (1 << n) - 1;
  const place = (cols, diag, anti) => {
    if (cols === full) return 1;
    let total = 0;
    let free = full & ~(cols | diag | anti);
    while (free) {
      const bit = free & -free;
      free -= bit;
      total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1);
    }
    return total;
  };
  return place(0, 0, 0);
}

class Solution {
    private int place(int cols, int diag, int anti, int full) {
        if (cols == full) return 1;
        int total = 0;
        int free = full & ~(cols | diag | anti);
        while (free != 0) {
            int bit = free & -free;
            free -= bit;
            total += place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1, full);
        }
        return total;
    }

    public int countQueens(int n) {
        return place(0, 0, 0, (1 << n) - 1);
    }
}

static int queens_place(int cols, int diag, int anti, int full) {
    if (cols == full) return 1;
    int total = 0;
    int free_cells = full & ~(cols | diag | anti);
    while (free_cells) {
        int bit = free_cells & -free_cells;
        free_cells -= bit;
        total += queens_place(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1, full);
    }
    return total;
}
int count_queens(int n) {
    return queens_place(0, 0, 0, (1 << n) - 1);
}

def has_nearby_duplicate(readings, k):
    for i in range(len(readings)):
        for j in range(i + 1, min(len(readings), i + k + 1)):
            if readings[i] == readings[j]:
                return True
    return False

def has_nearby_duplicate(readings, k):
    last = {}
    for i, x in enumerate(readings):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False

function hasNearbyDuplicate(readings, k) {
  const last = new Map();
  for (let i = 0; i < readings.length; i++) {
    const x = readings[i];
    if (last.has(x) && i - last.get(x) <= k) return true;
    last.set(x, i);
  }
  return false;
}

class Solution {
    public boolean hasNearbyDuplicate(int[] readings, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < readings.length; i++) {
            Integer prev = last.get(readings[i]);
            if (prev != null && i - prev <= k) return true;
            last.put(readings[i], i);
        }
        return false;
    }
}

bool has_nearby_duplicate(vector<int>& readings, int k) {
    unordered_map<int, int> last;
    for (int i = 0; i < (int) readings.size(); i++) {
        auto it = last.find(readings[i]);
        if (it != last.end() && i - it->second <= k) return true;
        last[readings[i]] = i;
    }
    return false;
}

def has_negative_cycle(n, edges):
    INF = 10 ** 15
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)
    for k in range(n):
        for i in range(n):
            if dist[i][k] >= INF:
                continue
            for j in range(n):
                if dist[k][j] < INF and dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return any(dist[i][i] < 0 for i in range(n))

def has_negative_cycle(n, edges):
    dist = [0] * n
    for _ in range(n):
        changed = False
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            return False
    return True

function hasNegativeCycle(n, edges) {
  const dist = new Array(n).fill(0);
  for (let round = 0; round < n; round++) {
    let changed = false;
    for (const [u, v, w] of edges) {
      if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; changed = true; }
    }
    if (!changed) return false;
  }
  return true;
}

class Solution {
    public boolean hasNegativeCycle(int n, int[][] edges) {
        long[] dist = new long[n];
        for (int round = 0; round < n; round++) {
            boolean changed = false;
            for (int[] e : edges) {
                if (dist[e[0]] + e[2] < dist[e[1]]) { dist[e[1]] = dist[e[0]] + e[2]; changed = true; }
            }
            if (!changed) return false;
        }
        return true;
    }
}

