    }
    return true;
}

def next_greater_circular(numbers):
    n = len(numbers)
    out = []
    for i in range(n):
        found = -1
        for step in range(1, n):
            v = numbers[(i + step) % n]
            if v > numbers[i]:
                found = v
                break
        out.append(found)
    return out

def next_greater_circular(numbers):
    n = len(numbers)
    out = [-1] * n
    stack = []
    for i in range(2 * n):
        x = numbers[i % n]
        while stack and numbers[stack[-1]] < x:
            out[stack.pop()] = x
        if i < n:
            stack.append(i)
    return out

function nextGreaterCircular(numbers) {
  const n = numbers.length, out = new Array(n).fill(-1), stack = [];
  for (let i = 0; i < 2 * n; i++) {
    const x = numbers[i % n];
    while (stack.length > 0 && numbers[stack[stack.length - 1]] < x) out[stack.pop()] = x;
    if (i < n) stack.push(i);
  }
  return out;
}

class Solution {
    public int[] nextGreaterCircular(int[] numbers) {
        int n = numbers.length;
        int[] out = new int[n];
        Arrays.fill(out, -1);
        int[] stack = new int[n];
        int size = 0;
        for (int i = 0; i < 2 * n; i++) {
            int x = numbers[i % n];
            while (size > 0 && numbers[stack[size - 1]] < x) out[stack[--size]] = x;
            if (i < n) stack[size++] = i;
        }
        return out;
    }
}

vector<int> next_greater_circular(vector<int>& numbers) {
    int n = (int) numbers.size();
    vector<int> out(n, -1), stack;
    for (int i = 0; i < 2 * n; i++) {
        int x = numbers[i % n];
        while (!stack.empty() && numbers[stack.back()] < x) { out[stack.back()] = x; stack.pop_back(); }
        if (i < n) stack.push_back(i);
    }
    return out;
}

def next_arrangement(nums):
    from itertools import permutations

    arrangements = sorted(set(permutations(nums)))
    index = arrangements.index(tuple(nums))
    return list(arrangements[(index + 1) % len(arrangements)])

def next_arrangement(nums):
    a = list(nums)
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

function nextArrangement(nums) {
  const a = [...nums];
  const n = a.length;
  let i = n - 2;
  while (i >= 0 && a[i] >= a[i + 1]) i--;
  if (i >= 0) {
    let j = n - 1;
    while (a[j] <= a[i]) j--;
    [a[i], a[j]] = [a[j], a[i]];
  }
  let lo = i + 1, hi = n - 1;
  while (lo < hi) { [a[lo], a[hi]] = [a[hi], a[lo]]; lo++; hi--; }
  return a;
}

class Solution {
    public int[] nextArrangement(int[] nums) {
        int[] a = nums.clone();
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (a[j] <= a[i]) j--;
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
        int lo = i + 1, hi = n - 1;
        while (lo < hi) { int t = a[lo]; a[lo] = a[hi]; a[hi] = t; lo++; hi--; }
        return a;
    }
}

vector<int> next_arrangement(vector<int>& nums) {
