    if (i >= 0) {
        int j = n - 1;
        while (a[j] <= a[i]) j--;
        swap(a[i], a[j]);
    }
    reverse(a.begin() + i + 1, a.end());
    return a;
}

def count_no_adjacent_ones(n):
    count = 0
    for mask in range(1 << n):
        if mask & (mask >> 1) == 0:  # no two neighbouring 1 bits
            count += 1
    return count

def count_no_adjacent_ones(n):
    memo = {}

    def go(remaining, last_is_one):
        if remaining == 0:
            return 1
        key = (remaining, last_is_one)
        if key not in memo:
            total = go(remaining - 1, False)
            if not last_is_one:
                total += go(remaining - 1, True)
            memo[key] = total
        return memo[key]

    return go(n, False)

