def count_nodes_at_distance(root, target, k):
    neighbours = {}

    def link(a, b):
        neighbours.setdefault(a, []).append(b)
        neighbours.setdefault(b, []).append(a)

    def walk(node):
        neighbours.setdefault(node.val, [])
        for child in (node.left, node.right):
            if child is not None:
                link(node.val, child.val)
                walk(child)

    walk(root)
    seen = {target}
    frontier = [target]
    for _ in range(k):
        nxt = []
        for v in frontier:
            for w in neighbours[v]:
                if w not in seen:
                    seen.add(w)
                    nxt.append(w)
        frontier = nxt
    return len(frontier)

def count_nodes_at_distance(root, target, k):
    found = [0]

    def collect(node, depth):
        if node is None:
            return 0
        if depth == 0:
            return 1
        return collect(node.left, depth - 1) + collect(node.right, depth - 1)

    def go(node):
        if node is None:
            return -1
        if node.val == target:
            found[0] += collect(node, k)
            return 0
        left = go(node.left)
        if left != -1:
            dist = left + 1
            if dist == k:
                found[0] += 1
            elif dist < k:
                found[0] += collect(node.right, k - dist - 1)
            return dist
        right = go(node.right)
        if right != -1:
            dist = right + 1
            if dist == k:
                found[0] += 1
            elif dist < k:
                found[0] += collect(node.left, k - dist - 1)
            return dist
        return -1

    go(root)
    return found[0]

function countNodesAtDistance(root, target, k) {
