def count_boomerangs(points):
    n = len(points)

    def d2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    total = 0
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if i != j and i != k and j != k and d2(points[i], points[j]) == d2(points[i], points[k]):
                    total += 1
    return total

def count_boomerangs(points):
    total = 0
    for i, p in enumerate(points):
        counts = {}
        for j, q in enumerate(points):
            if i != j:
                d = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
                counts[d] = counts.get(d, 0) + 1
        for c in counts.values():
            total += c * (c - 1)
    return total

function countBoomerangs(points) {
  let total = 0;
  for (let i = 0; i < points.length; i++) {
    const counts = new Map();
    for (let j = 0; j < points.length; j++) {
      if (i === j) continue;
      const dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
      const d = dx * dx + dy * dy;
      counts.set(d, (counts.get(d) || 0) + 1);
    }
    for (const c of counts.values()) total += c * (c - 1);
  }
  return total;
}

class Solution {
