}

def distinct_island_shapes(grid):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    shapes = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in seen:
                cells = [(r, c)]
                seen.add((r, c))
                for x, y in cells:
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            cells.append((nx, ny))
                top = min(x for x, y in cells)
                left = min(y for x, y in cells)
                shapes.add(tuple(sorted((x - top, y - left) for x, y in cells)))
    return len(shapes)

def distinct_island_shapes(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    shapes = set()

    def walk(x, y, direction, path):
        if not (0 <= x < rows and 0 <= y < cols) or grid[x][y] != 1 or visited[x][y]:
            return
        visited[x][y] = True
        path.append(direction)
        walk(x + 1, y, "d", path)
        walk(x - 1, y, "u", path)
        walk(x, y + 1, "r", path)
        walk(x, y - 1, "l", path)
        path.append("b")

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                path = []
                walk(r, c, "o", path)
                shapes.add("".join(path))
    return len(shapes)

function distinctIslandShapes(grid) {
  const rows = grid.length, cols = grid[0].length;
  const visited = [];
  for (let r = 0; r < rows; r++) visited.push(new Array(cols).fill(false));
  const shapes = new Set();
  function walk(x, y, direction, path) {
    if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] !== 1 || visited[x][y]) return;
    visited[x][y] = true;
    path.push(direction);
    walk(x + 1, y, "d", path);
    walk(x - 1, y, "u", path);
    walk(x, y + 1, "r", path);
    walk(x, y - 1, "l", path);
    path.push("b");
  }
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1 && !visited[r][c]) {
        const path = [];
        walk(r, c, "o", path);
        shapes.add(path.join(""));
      }
    }
  }
  return shapes.size;
}

class Solution {
    private int[][] grid;
    private boolean[][] visited;

    private void walk(int x, int y, char direction, StringBuilder path) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] != 1 || visited[x][y]) return;
        visited[x][y] = true;
        path.append(direction);
        walk(x + 1, y, 'd', path);
        walk(x - 1, y, 'u', path);
        walk(x, y + 1, 'r', path);
        walk(x, y - 1, 'l', path);
        path.append('b');
    }

    public int distinctIslandShapes(int[][] grid) {
        this.grid = grid;
        this.visited = new boolean[grid.length][grid[0].length];
        Set<String> shapes = new HashSet<>();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    StringBuilder path = new StringBuilder();
                    walk(r, c, 'o', path);
                    shapes.add(path.toString());
                }
            }
        }
