    sums = [0] * k

    def go(i):
        if i == len(nums):
            return all(s == target for s in sums)
        for g in range(k):
            sums[g] += nums[i]
            found = go(i + 1)
            sums[g] -= nums[i]
            if found:
                return True
        return False

    return go(0)

