            i += 1
    return best[n]

def min_perfect_squares(n):
    from math import isqrt

    root = isqrt(n)
    if root * root == n:
        return 1
    m = n
    while m % 4 == 0:
        m //= 4
    if m % 8 == 7:
        return 4
    i = 1
    while i * i <= n:
        rest = n - i * i
        r = isqrt(rest)
        if r * r == rest:
            return 2
        i += 1
    return 3

