def can_rearrange(letters):
    import heapq
    from collections import Counter

    heap = [(-c, ch) for ch, c in Counter(letters).items()]
    heapq.heapify(heap)
    held = None
    while heap or held:
        if not heap:
            return False
        count, ch = heapq.heappop(heap)
