def min_join_cost(ropes):
    ropes = list(ropes)
    if len(ropes) == 1:
        return 0
    best = None
    for i in range(len(ropes)):
        for j in range(i + 1, len(ropes)):
            joined = ropes[i] + ropes[j]
            rest = [ropes[k] for k in range(len(ropes)) if k != i and k != j] + [joined]
            cost = joined + min_join_cost(rest)
            if best is None or cost < best:
                best = cost
    return best

function minJoinCost(ropes) {
  const heap = [];
  const push = (v) => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  for (const r of ropes) push(r);
  let total = 0;
  while (heap.length > 1) {
    const a = pop(), b = pop();
    total += a + b;
    push(a + b);
  }
  return total;
}

class Solution {
    public int minJoinCost(int[] ropes) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int r : ropes) heap.add(r);
        int total = 0;
        while (heap.size() > 1) {
            int a = heap.poll(), b = heap.poll();
            total += a + b;
            heap.add(a + b);
        }
        return total;
    }
}

