def shortest_cycle_length(n, edges):
    adjacent = [set() for _ in range(n)]
    for a, b in edges:
        adjacent[a].add(b)
        adjacent[b].add(a)
    best = [0]

    def walk(start, node, visited, length):
        for nxt in adjacent[node]:
            if nxt == start and length >= 3:
                if best[0] == 0 or length < best[0]:
                    best[0] = length
            elif nxt > start and nxt not in visited:
                visited.add(nxt)
                walk(start, nxt, visited, length + 1)
                visited.remove(nxt)

    for s in range(n):
        walk(s, s, {s}, 1)
    return best[0] if best[0] else -1

def shortest_cycle_length(n, edges):
    from collections import deque

    adjacent = [[] for _ in range(n)]
    for a, b in edges:
        adjacent[a].append(b)
        adjacent[b].append(a)
    best = 10 ** 9
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adjacent[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    best = min(best, dist[u] + dist[v] + 1)
    return -1 if best == 10 ** 9 else best

function shortestCycleLength(n, edges) {
  const adjacent = [];
  for (let i = 0; i < n; i++) adjacent.push([]);
  for (const [a, b] of edges) { adjacent[a].push(b); adjacent[b].push(a); }
  let best = Infinity;
  for (let s = 0; s < n; s++) {
    const dist = new Array(n).fill(-1), parent = new Array(n).fill(-1);
    dist[s] = 0;
    const queue = [s];
    for (let head = 0; head < queue.length; head++) {
      const u = queue[head];
      for (const v of adjacent[u]) {
        if (dist[v] === -1) { dist[v] = dist[u] + 1; parent[v] = u; queue.push(v); }
        else if (parent[u] !== v) best = Math.min(best, dist[u] + dist[v] + 1);
      }
    }
  }
  return best === Infinity ? -1 : best;
}

class Solution {
    public int shortestCycleLength(int n, int[][] edges) {
        List<List<Integer>> adjacent = new ArrayList<>();
        for (int i = 0; i < n; i++) adjacent.add(new ArrayList<>());
        for (int[] e : edges) { adjacent.get(e[0]).add(e[1]); adjacent.get(e[1]).add(e[0]); }
        int best = Integer.MAX_VALUE;
        for (int s = 0; s < n; s++) {
            int[] dist = new int[n], parent = new int[n];
            Arrays.fill(dist, -1);
            Arrays.fill(parent, -1);
            dist[s] = 0;
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.add(s);
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adjacent.get(u)) {
                    if (dist[v] == -1) { dist[v] = dist[u] + 1; parent[v] = u; queue.add(v); }
                    else if (parent[u] != v) best = Math.min(best, dist[u] + dist[v] + 1);
                }
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

