    return best if best <= n else -1

def shortest_sum_at_least(numbers, target):
    from collections import deque

    prefix = [0]
    for x in numbers:
        prefix.append(prefix[-1] + x)
    best = len(numbers) + 1
    window = deque()
    for j, p in enumerate(prefix):
        while window and p - prefix[window[0]] >= target:
            best = min(best, j - window.popleft())
        while window and prefix[window[-1]] >= p:
            window.pop()
        window.append(j)
    return best if best <= len(numbers) else -1

function shortestSumAtLeast(numbers, target) {
  const n = numbers.length;
  const prefix = [0];
  for (const x of numbers) prefix.push(prefix[prefix.length - 1] + x);
  let best = n + 1;
  const window = [];
  let head = 0;
  for (let j = 0; j <= n; j++) {
    while (head < window.length && prefix[j] - prefix[window[head]] >= target) {
      best = Math.min(best, j - window[head]);
      head++;
    }
    while (head < window.length && prefix[window[window.length - 1]] >= prefix[j]) window.pop();
    window.push(j);
  }
  return best <= n ? best : -1;
}

class Solution {
    public int shortestSumAtLeast(int[] numbers, int target) {
        int n = numbers.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + numbers[i];
        int best = n + 1;
        Deque<Integer> window = new ArrayDeque<>();
        for (int j = 0; j <= n; j++) {
            while (!window.isEmpty() && prefix[j] - prefix[window.peekFirst()] >= target) best = Math.min(best, j - window.pollFirst());
            while (!window.isEmpty() && prefix[window.peekLast()] >= prefix[j]) window.pollLast();
            window.addLast(j);
        }
        return best <= n ? best : -1;
    }
