def signal_spread_time(stations, links, source):
    INF = float("inf")
    dist = [INF] * stations
    dist[source] = 0
    for _ in range(stations):
        for a, b, t in links:
            if dist[a] + t < dist[b]:
                dist[b] = dist[a] + t
    worst = max(dist)
    return -1 if worst == INF else worst

def signal_spread_time(stations, links, source):
    import heapq

    adj = [[] for _ in range(stations)]
    for a, b, t in links:
        adj[a].append((b, t))
    best = [None] * stations
    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if best[u] is not None:
            continue
        best[u] = d
        for v, t in adj[u]:
            if best[v] is None:
                heapq.heappush(heap, (d + t, v))
    if any(b is None for b in best):
        return -1
    return max(best)

function signalSpreadTime(stations, links, source) {
  const adj = Array.from({ length: stations }, () => []);
  for (const [a, b, t] of links) adj[a].push([b, t]);
  const best = new Array(stations).fill(-1);
  // a simple heap-free version is fine for 100 stations: pick the closest unfinished station each round
  const dist = new Array(stations).fill(Infinity);
  dist[source] = 0;
  for (let round = 0; round < stations; round++) {
    let u = -1;
    for (let i = 0; i < stations; i++) {
      if (best[i] === -1 && dist[i] !== Infinity && (u === -1 || dist[i] < dist[u])) u = i;
    }
    if (u === -1) break;
    best[u] = dist[u];
    for (const [v, t] of adj[u]) if (best[v] === -1 && dist[u] + t < dist[v]) dist[v] = dist[u] + t;
  }
  let worst = 0;
  for (let i = 0; i < stations; i++) {
    if (best[i] === -1) return -1;
    worst = Math.max(worst, best[i]);
  }
  return worst;
}

class Solution {
    public int signalSpreadTime(int stations, int[][] links, int source) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < stations; i++) adj.add(new ArrayList<>());
        for (int[] l : links) adj.get(l[0]).add(new int[]{l[1], l[2]});
        int[] best = new int[stations];
        Arrays.fill(best, -1);
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        heap.add(new int[]{0, source});
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            int d = top[0], u = top[1];
            if (best[u] != -1) continue;
            best[u] = d;
            for (int[] e : adj.get(u)) {
                if (best[e[0]] == -1) heap.add(new int[]{d + e[1], e[0]});
            }
        }
        int worst = 0;
        for (int b : best) {
            if (b == -1) return -1;
            worst = Math.max(worst, b);
        }
        return worst;
    }
}

int signal_spread_time(int stations, vector<vector<int>>& links, int source) {
    vector<vector<pair<int,int>>> adj(stations);
    for (auto& l : links) adj[l[0]].push_back({l[1], l[2]});
    vector<int> best(stations, -1);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> heap;
    heap.push({0, source});
    while (!heap.empty()) {
        auto top = heap.top(); heap.pop();
        int d = top.first, u = top.second;
        if (best[u] != -1) continue;
        best[u] = d;
        for (auto& e : adj[u]) {
            if (best[e.first] == -1) heap.push({d + e.second, e.first});
        }
    }
    int worst = 0;
    for (int b : best) {
        if (b == -1) return -1;
        worst = max(worst, b);
    }
    return worst;
}

