function smallestBuildOrder(n, pairs) {
  const count = new Array(n).fill(0), later = [];
  for (let i = 0; i < n; i++) later.push([]);
  for (const [a, b] of pairs) { count[b]++; later[a].push(b); }
  const heap = [];
  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[i] < heap[p]) { const t = heap[i]; heap[i] = heap[p]; heap[p] = t; i = p; } else break;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        const t = heap[i]; heap[i] = heap[m]; heap[m] = t;
        i = m;
      }
    }
    return top;
  };
  for (let job = 0; job < n; job++) if (count[job] === 0) push(job);
  const order = [];
  while (heap.length > 0) {
    const job = pop();
    order.push(job);
    for (const b of later[job]) {
      count[b]--;
      if (count[b] === 0) push(b);
    }
  }
  return order.length === n ? order : [];
}

class Solution {
    public int[] smallestBuildOrder(int n, int[][] pairs) {
        int[] count = new int[n];
        List<List<Integer>> later = new ArrayList<>();
        for (int i = 0; i < n; i++) later.add(new ArrayList<>());
        for (int[] pair : pairs) { count[pair[1]]++; later.get(pair[0]).add(pair[1]); }
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int job = 0; job < n; job++) if (count[job] == 0) heap.add(job);
        int[] order = new int[n];
        int placed = 0;
        while (!heap.isEmpty()) {
            int job = heap.poll();
            order[placed++] = job;
            for (int b : later.get(job)) {
                if (--count[b] == 0) heap.add(b);
            }
        }
        return placed == n ? order : new int[0];
    }
}

