        slow.next = null;
        return merge(sortList(head), sortList(middle));
    }
}

static ListNode* merge_sorted_nodes(ListNode* a, ListNode* b) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (a != nullptr && b != nullptr) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a != nullptr ? a : b;
    return dummy.next;
}
ListNode* sort_list(ListNode* head) {
    if (head == nullptr || head->next == nullptr) return head;
    ListNode *slow = head, *fast = head->next;
    while (fast != nullptr && fast->next != nullptr) { slow = slow->next; fast = fast->next->next; }
    ListNode* middle = slow->next;
    slow->next = nullptr;
    return merge_sorted_nodes(sort_list(head), sort_list(middle));
}

def sort_three_values(numbers):
    a = list(numbers)
    low, mid, high = 0, 0, len(a) - 1
    while mid <= high:
        if a[mid] == 0:
            a[low], a[mid] = a[mid], a[low]
            low += 1
            mid += 1
        elif a[mid] == 1:
            mid += 1
        else:
            a[mid], a[high] = a[high], a[mid]
            high -= 1
    return a

function sortThreeValues(numbers) {
  const a = numbers.slice();
  let low = 0, mid = 0, high = a.length - 1;
  while (mid <= high) {
    if (a[mid] === 0) { [a[low], a[mid]] = [a[mid], a[low]]; low++; mid++; }
    else if (a[mid] === 1) mid++;
    else { [a[mid], a[high]] = [a[high], a[mid]]; high--; }
  }
  return a;
}

