def spiral_walk(grid):
    top, bottom = 0, len(grid) - 1
    left, right = 0, len(grid[0]) - 1
    out = []
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(grid[top][c])
        for r in range(top + 1, bottom + 1):
            out.append(grid[r][right])
        if top < bottom and left < right:
            for c in range(right - 1, left - 1, -1):
                out.append(grid[bottom][c])
            for r in range(bottom - 1, top, -1):
                out.append(grid[r][left])
        top += 1
        bottom -= 1
        left += 1
        right -= 1
    return out

function spiralWalk(grid) {
  let top = 0, bottom = grid.length - 1, left = 0, right = grid[0].length - 1;
  const out = [];
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) out.push(grid[top][c]);
    for (let r = top + 1; r <= bottom; r++) out.push(grid[r][right]);
    if (top < bottom && left < right) {
      for (let c = right - 1; c >= left; c--) out.push(grid[bottom][c]);
      for (let r = bottom - 1; r > top; r--) out.push(grid[r][left]);
    }
    top++; bottom--; left++; right--;
  }
  return out;
}

class Solution {
    public int[] spiralWalk(int[][] grid) {
        int top = 0, bottom = grid.length - 1, left = 0, right = grid[0].length - 1;
        int[] out = new int[grid.length * grid[0].length];
        int k = 0;
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++) out[k++] = grid[top][c];
            for (int r = top + 1; r <= bottom; r++) out[k++] = grid[r][right];
            if (top < bottom && left < right) {
                for (int c = right - 1; c >= left; c--) out[k++] = grid[bottom][c];
                for (int r = bottom - 1; r > top; r--) out[k++] = grid[r][left];
            }
            top++; bottom--; left++; right--;
        }
        return out;
    }
}

vector<int> spiral_walk(vector<vector<int>>& grid) {
    int top = 0, bottom = (int) grid.size() - 1, left = 0, right = (int) grid[0].size() - 1;
