            for (int r = bottom - 1; r > top; r--) out.push_back(grid[r][left]);
        }
        top++; bottom--; left++; right--;
    }
    return out;
}

def spread_stalls(positions, animals):
    a = sorted(positions)
    for d in range(a[-1] - a[0], 0, -1):
        placed = 1
        last = a[0]
        for p in a[1:]:
            if p - last >= d:
                placed += 1
                last = p
        if placed >= animals:
            return d
    return 0

def spread_stalls(positions, animals):
    a = sorted(positions)

    def fits(d):
        placed = 1
        last = a[0]
        for p in a[1:]:
            if p - last >= d:
                placed += 1
                last = p
        return placed >= animals

    lo, hi = 1, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if fits(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

function spreadStalls(positions, animals) {
  const a = positions.slice().sort((p, q) => p - q);
  function fits(d) {
    let placed = 1, last = a[0];
    for (let i = 1; i < a.length; i++) {
      if (a[i] - last >= d) { placed++; last = a[i]; }
    }
    return placed >= animals;
  }
  let lo = 1, hi = a[a.length - 1] - a[0];
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo + 1) / 2);
    if (fits(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

class Solution {
    private boolean fits(int[] a, int animals, int d) {
        int placed = 1, last = a[0];
        for (int i = 1; i < a.length; i++) {
            if (a[i] - last >= d) { placed++; last = a[i]; }
        }
        return placed >= animals;
    }

