def count_ways(n):
    if n < 0:
        return 0
    if n == 0:
        return 1
    return count_ways(n - 1) + count_ways(n - 2) + count_ways(n - 3)

def count_ways(n):
    memo = {}

    def go(k):
        if k < 0:
            return 0
        if k == 0:
            return 1
        if k not in memo:
            memo[k] = go(k - 1) + go(k - 2) + go(k - 3)
        return memo[k]

    return go(n)

