                return True
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in seen and grid[nx][ny] <= t:
                    seen.add((nx, ny))
                    stack.append((nx, ny))
        return False

    lo, hi = 0, max(max(row) for row in grid)
    while lo < hi:
        mid = (lo + hi) // 2
        if reachable(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def swim_time(grid):
    import heapq

    n = len(grid)
    heap = [(grid[0][0], 0, 0)]
    visited = [[False] * n for _ in range(n)]
    visited[0][0] = True
    while heap:
        t, x, y = heapq.heappop(heap)
        if x == n - 1 and y == n - 1:
            return t
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                heapq.heappush(heap, (max(t, grid[nx][ny]), nx, ny))
    return 0

function swimTime(grid) {
  const n = grid.length;
  function heapPush(a, x) {
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[i][0] < a[p][0]) { const t = a[i]; a[i] = a[p]; a[p] = t; i = p; } else break;
    }
  }
  function heapPop(a) {
    const top = a[0], last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        const t = a[i]; a[i] = a[m]; a[m] = t;
        i = m;
      }
    }
    return top;
  }
  const visited = [];
  for (let r = 0; r < n; r++) visited.push(new Array(n).fill(false));
  const heap = [[grid[0][0], 0, 0]];
  visited[0][0] = true;
  const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
  while (heap.length > 0) {
    const [t, x, y] = heapPop(heap);
    if (x === n - 1 && y === n - 1) return t;
    for (let d = 0; d < 4; d++) {
      const nx = x + dr[d], ny = y + dc[d];
      if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
        visited[nx][ny] = true;
        heapPush(heap, [Math.max(t, grid[nx][ny]), nx, ny]);
      }
    }
  }
  return 0;
}

class Solution {
