def remaining_gifts(gifts, k):
    import heapq
    from math import isqrt

    heap = [-g for g in gifts]
    heapq.heapify(heap)
    for _ in range(k):
        if not heap:
            break
        x = -heapq.heappop(heap)
        heapq.heappush(heap, -isqrt(x))
    return -sum(heap)

function heapPush(a, x, less) {
  a.push(x);
  let i = a.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (less(a[i], a[p])) { const t = a[i]; a[i] = a[p]; a[p] = t; i = p; } else break;
  }
}
function heapPop(a, less) {
  const top = a[0];
  const last = a.pop();
  if (a.length > 0) {
    a[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < a.length && less(a[l], a[m])) m = l;
      if (r < a.length && less(a[r], a[m])) m = r;
      if (m === i) break;
      const t = a[i]; a[i] = a[m]; a[m] = t;
      i = m;
    }
  }
  return top;
}
function remainingGifts(gifts, k) {
  const bigger = (p, q) => p > q;
  const heap = [];
  for (const g of gifts) heapPush(heap, g, bigger);
  for (let i = 0; i < k && heap.length > 0; i++) {
    const x = heapPop(heap, bigger);
    heapPush(heap, Math.floor(Math.sqrt(x)), bigger);
  }
  let total = 0;
  for (const g of heap) total += g;
  return total;
}

class Solution {
    public int remainingGifts(int[] gifts, int k) {
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int g : gifts) heap.add((long) g);
        for (int i = 0; i < k && !heap.isEmpty(); i++) {
            long x = heap.poll();
            long root = (long) Math.sqrt((double) x);
            while (root * root > x) root--;
            while ((root + 1) * (root + 1) <= x) root++;
            heap.add(root);
        }
        long total = 0;
        for (long g : heap) total += g;
        return (int) total;
    }
}

