        while ((root + 1) * (root + 1) <= x) root++;
        heap.push(root);
    }
    long long total = 0;
    while (!heap.empty()) { total += heap.top(); heap.pop(); }
    return (int) total;
}

def min_taps(ranges):
    n = len(ranges) - 1
    INF = 10 ** 9
    best = [INF] * (n + 1)
    best[0] = 0
    for x in range(1, n + 1):
        for i, r in enumerate(ranges):
            left = max(0, i - r)
            right = min(n, i + r)
            if left <= x - 1 and right >= x and best[left] + 1 < best[x]:
                best[x] = best[left] + 1
    return -1 if best[n] >= INF else best[n]

def min_taps(ranges):
    n = len(ranges) - 1
    furthest = [0] * (n + 1)
    for i, r in enumerate(ranges):
        left = max(0, i - r)
        furthest[left] = max(furthest[left], i + r)
    taps = 0
    current_end = 0
    far = 0
    for i in range(n):
        far = max(far, furthest[i])
        if i == current_end:
            if far <= i:
                return -1
            taps += 1
            current_end = far
            if current_end >= n:
                return taps
    return -1

