def count_expressions(digits, target):
    from itertools import product

    n = len(digits)
    count = 0
    for ops in product(["", "+", "-", "*"], repeat=n - 1):
        expr = digits[0]
        for op, d in zip(ops, digits[1:]):
            expr += op + d
        parts = expr.replace("+", " ").replace("-", " ").replace("*", " ").split()
        if any(len(p) > 1 and p[0] == "0" for p in parts):
            continue
        if eval(expr) == target:
            count += 1
    return count

def count_expressions(digits, target):
    n = len(digits)

    def go(pos, value, last):
        if pos == n:
            return 1 if value == target else 0
        total = 0
        for end in range(pos + 1, n + 1):
            if end - pos > 1 and digits[pos] == "0":
                break
            num = int(digits[pos:end])
            if pos == 0:
                total += go(end, num, num)
            else:
                total += go(end, value + num, num)
                total += go(end, value - num, -num)
                total += go(end, value - last + last * num, last * num)
        return total

    return go(0, 0, 0)

function countExpressions(digits, target) {
  const n = digits.length;
  function go(pos, value, last) {
    if (pos === n) return value === target ? 1 : 0;
    let total = 0;
    for (let end = pos + 1; end <= n; end++) {
      if (end - pos > 1 && digits[pos] === "0") break;
      const num = Number(digits.slice(pos, end));
      if (pos === 0) total += go(end, num, num);
      else {
        total += go(end, value + num, num);
        total += go(end, value - num, -num);
        total += go(end, value - last + last * num, last * num);
      }
    }
    return total;
  }
  return go(0, 0, 0);
}

