def signed_sum_ways(numbers, target):
    from itertools import product

    return sum(1 for signs in product((1, -1), repeat=len(numbers)) if sum(s * x for s, x in zip(signs, numbers)) == target)

def signed_sum_ways(numbers, target):
    total = sum(numbers)
    if abs(target) > total or (total + target) % 2:
        return 0
    want = (total + target) // 2
    ways = [0] * (want + 1)
    ways[0] = 1
    for x in numbers:
        for s in range(want, x - 1, -1):
            ways[s] += ways[s - x]
    return ways[want]

function signedSumWays(numbers, target) {
  let total = 0;
  for (const x of numbers) total += x;
  if (Math.abs(target) > total || (total + target) % 2 !== 0) return 0;
  const want = (total + target) / 2;
  const ways = new Array(want + 1).fill(0);
  ways[0] = 1;
  for (const x of numbers) {
    for (let s = want; s >= x; s--) ways[s] += ways[s - x];
  }
  return ways[want];
}

