def task_cooldown_time(tasks, cooldown):
    counts = {}
    for t in tasks:
        counts[t] = counts.get(t, 0) + 1
    last = {}
    time = 0
    left = len(tasks)
    while left:
        best = None
        for t in sorted(counts):
            if counts[t] > 0 and (t not in last or time - last[t] > cooldown):
                if best is None or counts[t] > counts[best]:
                    best = t
        if best is not None:
            counts[best] -= 1
            last[best] = time
            left -= 1
        time += 1
    return time

def task_cooldown_time(tasks, cooldown):
    if not tasks:
        return 0
    counts = {}
    for t in tasks:
        counts[t] = counts.get(t, 0) + 1
    top = max(counts.values())
    num_top = sum(1 for c in counts.values() if c == top)
    return max(len(tasks), (top - 1) * (cooldown + 1) + num_top)

function taskCooldownTime(tasks, cooldown) {
  if (tasks.length === 0) return 0;
  const counts = new Array(26).fill(0);
  for (const ch of tasks) counts[ch.charCodeAt(0) - 65]++;
  let top = 0;
  for (const c of counts) top = Math.max(top, c);
  let numTop = 0;
  for (const c of counts) if (c === top) numTop++;
  return Math.max(tasks.length, (top - 1) * (cooldown + 1) + numTop);
}

