def tidy_sentence(text):
    words = []
    i = len(text) - 1
    while i >= 0:
        while i >= 0 and text[i] == " ":
            i -= 1
        if i < 0:
            break
        j = i
        while i >= 0 and text[i] != " ":
            i -= 1
        words.append(text[i + 1:j + 1])
    return " ".join(words)

function tidySentence(text) {
  const words = [];
  let i = text.length - 1;
  while (i >= 0) {
    while (i >= 0 && text[i] === " ") i--;
    if (i < 0) break;
    const j = i;
    while (i >= 0 && text[i] !== " ") i--;
    words.push(text.slice(i + 1, j + 1));
  }
  return words.join(" ");
}

class Solution {
    public String tidySentence(String text) {
        List<String> words = new ArrayList<>();
        int i = text.length() - 1;
        while (i >= 0) {
            while (i >= 0 && text.charAt(i) == ' ') i--;
            if (i < 0) break;
            int j = i;
            while (i >= 0 && text.charAt(i) != ' ') i--;
            words.add(text.substring(i + 1, j + 1));
        }
        return String.join(" ", words);
    }
}

string tidy_sentence(string text) {
    vector<string> words;
    int i = (int) text.size() - 1;
    while (i >= 0) {
        while (i >= 0 && text[i] == ' ') i--;
        if (i < 0) break;
        int j = i;
        while (i >= 0 && text[i] != ' ') i--;
        words.push_back(text.substr(i + 1, j - i));
    }
    string out;
    for (size_t k = 0; k < words.size(); k++) {
        if (k > 0) out += ' ';
        out += words[k];
    }
