def top_k_frequent(nums, k):
    import heapq

    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    heap = []  # (count, -value): the smallest tuple is the worst of the best k
    for value, count in counts.items():
        heapq.heappush(heap, (count, -value))
