def trapped_water_2d(heights):
    import heapq

    rows, cols = len(heights), len(heights[0])
    seen = [[False] * cols for _ in range(rows)]
    heap = []
    for r in range(rows):
        for c in range(cols):
            if r in (0, rows - 1) or c in (0, cols - 1):
                heapq.heappush(heap, (heights[r][c], r, c))
                seen[r][c] = True
    total = 0
    while heap:
        h, r, c = heapq.heappop(heap)
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and not seen[nr][nc]:
                seen[nr][nc] = True
                total += max(0, h - heights[nr][nc])
                heapq.heappush(heap, (max(h, heights[nr][nc]), nr, nc))
    return total

function heapPush(a, x, less) {
  a.push(x);
  let i = a.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (less(a[i], a[p])) { const t = a[i]; a[i] = a[p]; a[p] = t; i = p; } else break;
  }
}
function heapPop(a, less) {
  const top = a[0];
  const last = a.pop();
  if (a.length > 0) {
    a[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < a.length && less(a[l], a[m])) m = l;
      if (r < a.length && less(a[r], a[m])) m = r;
      if (m === i) break;
      const t = a[i]; a[i] = a[m]; a[m] = t;
      i = m;
    }
  }
  return top;
}
function trappedWater2d(heights) {
  const rows = heights.length, cols = heights[0].length;
  const seen = [];
  for (let r = 0; r < rows; r++) seen.push(new Array(cols).fill(false));
  const less = (p, q) => p[0] < q[0];
  const heap = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (r === 0 || r === rows - 1 || c === 0 || c === cols - 1) { heapPush(heap, [heights[r][c], r, c], less); seen[r][c] = true; }
    }
  }
  const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
  let total = 0;
  while (heap.length > 0) {
    const [h, r, c] = heapPop(heap, less);
    for (let d = 0; d < 4; d++) {
      const nr = r + dr[d], nc = c + dc[d];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc]) {
        seen[nr][nc] = true;
        total += Math.max(0, h - heights[nr][nc]);
        heapPush(heap, [Math.max(h, heights[nr][nc]), nr, nc], less);
      }
    }
  }
  return total;
}

class Solution {
    public int trappedWater2d(int[][] heights) {
        int rows = heights.length, cols = heights[0].length;
        boolean[][] seen = new boolean[rows][cols];
        PriorityQueue<int[]> heap = new PriorityQueue<>((p, q) -> Integer.compare(p[0], q[0]));
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) { heap.add(new int[]{heights[r][c], r, c}); seen[r][c] = true; }
            }
        }
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        long total = 0;
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            int h = top[0], r = top[1], c = top[2];
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc]) {
                    seen[nr][nc] = true;
                    total += Math.max(0, h - heights[nr][nc]);
                    heap.add(new int[]{Math.max(h, heights[nr][nc]), nr, nc});
                }
            }
        }
        return (int) total;
    }
}

