        if all((mask >> a & 1) != (mask >> b & 1) for a, b in conflicts):
            return True
    return False

def can_split_in_two(people, conflicts):
    adj = [[] for _ in range(people)]
    for a, b in conflicts:
        adj[a].append(b)
        adj[b].append(a)
    side = [-1] * people
    for s in range(people):
        if side[s] != -1:
            continue
        side[s] = 0
        queue = [s]
        for u in queue:
            for v in adj[u]:
                if side[v] == -1:
                    side[v] = 1 - side[u]
                    queue.append(v)
                elif side[v] == side[u]:
                    return False
    return True

function canSplitInTwo(people, conflicts) {
  const adj = Array.from({ length: people }, () => []);
  for (const [a, b] of conflicts) { adj[a].push(b); adj[b].push(a); }
  const side = new Array(people).fill(-1);
  for (let s = 0; s < people; s++) {
    if (side[s] !== -1) continue;
    side[s] = 0;
    const queue = [s];
    for (let head = 0; head < queue.length; head++) {
      const u = queue[head];
      for (const v of adj[u]) {
        if (side[v] === -1) { side[v] = 1 - side[u]; queue.push(v); }
        else if (side[v] === side[u]) return false;
      }
    }
  }
  return true;
}

class Solution {
    public boolean canSplitInTwo(int people, int[][] conflicts) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < people; i++) adj.add(new ArrayList<>());
        for (int[] e : conflicts) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] side = new int[people];
