            if (side[s] != -1) continue;
            side[s] = 0;
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(s);
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adj.get(u)) {
                    if (side[v] == -1) { side[v] = 1 - side[u]; queue.add(v); }
                    else if (side[v] == side[u]) return false;
                }
            }
        }
        return true;
    }
}

bool can_split_in_two(int people, vector<vector<int>>& conflicts) {
