def visible_from_right(root):
    seen = []

    def walk(node, depth):
        if node is None:
            return
        walk(node.left, depth + 1)
        seen.append((depth, node.val))
        walk(node.right, depth + 1)

    walk(root, 0)
    last = {}
    for depth, val in seen:
        last[depth] = val
    return [last[d] for d in sorted(last)]

