def min_water_cost(wells, pipes):
    n = len(wells)
    INF = 10 ** 18
    weight = [[INF] * (n + 1) for _ in range(n + 1)]
    for i, w in enumerate(wells):
        weight[i][n] = weight[n][i] = w
    for a, b, cost in pipes:
        weight[a][b] = weight[b][a] = min(weight[a][b], cost)
    in_tree = [False] * (n + 1)
    best = [INF] * (n + 1)
    best[n] = 0
    total = 0
    for _ in range(n + 1):
        u = min((v for v in range(n + 1) if not in_tree[v]), key=lambda v: best[v])
        in_tree[u] = True
        total += best[u]
        for v in range(n + 1):
            if not in_tree[v] and weight[u][v] < best[v]:
                best[v] = weight[u][v]
    return total

function minWaterCost(wells, pipes) {
  const n = wells.length;
  const edges = pipes.map(([a, b, cost]) => [cost, a, b]);
  for (let i = 0; i < n; i++) edges.push([wells[i], i, n]);
  edges.sort((x, y) => x[0] - y[0]);
  const parent = [];
  for (let i = 0; i <= n; i++) parent.push(i);
  function find(x) {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  }
  let total = 0;
  for (const [cost, a, b] of edges) {
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; total += cost; }
  }
  return total;
}

