        if pattern[j] == "*":
            return go(i, j + 1) or (i < len(text) and go(i + 1, j))
        return i < len(text) and (pattern[j] == "?" or pattern[j] == text[i]) and go(i + 1, j + 1)

    return go(0, 0)

