def window_distinct_counts(numbers, k):
    counts = {}
    out = []
    for i, x in enumerate(numbers):
        counts[x] = counts.get(x, 0) + 1
        if i >= k:
            y = numbers[i - k]
            counts[y] -= 1
            if counts[y] == 0:
                del counts[y]
        if i >= k - 1:
            out.append(len(counts))
    return out

function windowDistinctCounts(numbers, k) {
  const counts = new Map(), out = [];
  for (let i = 0; i < numbers.length; i++) {
    counts.set(numbers[i], (counts.get(numbers[i]) || 0) + 1);
    if (i >= k) {
      const y = numbers[i - k];
      counts.set(y, counts.get(y) - 1);
      if (counts.get(y) === 0) counts.delete(y);
    }
    if (i >= k - 1) out.push(counts.size);
  }
  return out;
}

class Solution {
    public int[] windowDistinctCounts(int[] numbers, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < numbers.length; i++) {
            counts.merge(numbers[i], 1, Integer::sum);
            if (i >= k) {
                int y = numbers[i - k];
                if (counts.merge(y, -1, Integer::sum) == 0) counts.remove(y);
            }
            if (i >= k - 1) out.add(counts.size());
        }
        int[] result = new int[out.size()];
        for (int i = 0; i < result.length; i++) result[i] = out.get(i);
        return result;
    }
}

