def zigzag_levels(root):
    levels = []

    def walk(node, depth):
        if node is None:
            return
        if depth == len(levels):
            levels.append([])
        levels[depth].append(node.val)
        walk(node.left, depth + 1)
        walk(node.right, depth + 1)

    walk(root, 0)
    out = []
    for d, level in enumerate(levels):
        out += level if d % 2 == 0 else level[::-1]
    return out

function zigzagLevels(root) {
  const out = [];
  let level = root === null ? [] : [root];
  let leftToRight = true;
  while (level.length > 0) {
    const values = level.map((node) => node.val);
    if (!leftToRight) values.reverse();
    for (const v of values) out.push(v);
    const next = [];
    for (const node of level) {
      if (node.left !== null) next.push(node.left);
      if (node.right !== null) next.push(node.right);
    }
    level = next;
    leftToRight = !leftToRight;
  }
  return out;
}

class Solution {
    public int[] zigzagLevels(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        List<TreeNode> level = new ArrayList<>();
        if (root != null) level.add(root);
        boolean leftToRight = true;
        while (!level.isEmpty()) {
            List<Integer> values = new ArrayList<>();
            for (TreeNode node : level) values.add(node.val);
            if (!leftToRight) Collections.reverse(values);
            out.addAll(values);
            List<TreeNode> next = new ArrayList<>();
            for (TreeNode node : level) {
                if (node.left != null) next.add(node.left);
                if (node.right != null) next.add(node.right);
            }
            level = next;
            leftToRight = !leftToRight;
        }
        int[] result = new int[out.size()];
        for (int i = 0; i < result.length; i++) result[i] = out.get(i);
        return result;
    }
}

vector<int> zigzag_levels(TreeNode* root) {
    vector<int> out;
    vector<TreeNode*> level;
    if (root != nullptr) level.push_back(root);
    bool left_to_right = true;
    while (!level.empty()) {
        vector<int> values;
        for (TreeNode* node : level) values.push_back(node->val);
        if (!left_to_right) reverse(values.begin(), values.end());
        for (int v : values) out.push_back(v);
        vector<TreeNode*> next;
        for (TreeNode* node : level) {
            if (node->left != nullptr) next.push_back(node->left);
            if (node->right != nullptr) next.push_back(node->right);
        }
        level = next;
        left_to_right = !left_to_right;
    }
    return out;
}

def zigzag_read(text, rows):
    if rows == 1:
        return text
    cycle = 2 * (rows - 1)
    out = []
    for r in range(rows):
        for i, ch in enumerate(text):
            pos = i % cycle
            row = pos if pos < rows else cycle - pos
            if row == r:
                out.append(ch)
    return "".join(out)

def zigzag_read(text, rows):
    if rows == 1 or rows >= len(text):
        return text
    lines = [[] for _ in range(rows)]
    row, step = 0, 1
    for ch in text:
        lines[row].append(ch)
        if row == 0:
            step = 1
        elif row == rows - 1:
            step = -1
        row += step
    return "".join("".join(line) for line in lines)

function zigzagRead(text, rows) {
  if (rows === 1 || rows >= text.length) return text;
  const lines = Array.from({ length: rows }, () => []);
  let row = 0, step = 1;
  for (const ch of text) {
    lines[row].push(ch);
    if (row === 0) step = 1;
    else if (row === rows - 1) step = -1;
    row += step;
  }
  return lines.map((line) => line.join("")).join("");
}

class Solution {
    public String zigzagRead(String text, int rows) {
        if (rows == 1 || rows >= text.length()) return text;
        StringBuilder[] lines = new StringBuilder[rows];
        for (int i = 0; i < rows; i++) lines[i] = new StringBuilder();
        int row = 0, step = 1;
        for (char ch : text.toCharArray()) {
            lines[row].append(ch);
            if (row == 0) step = 1;
            else if (row == rows - 1) step = -1;
            row += step;
        }
        StringBuilder out = new StringBuilder();
        for (StringBuilder line : lines) out.append(line);
        return out.toString();
    }
}

